window.__FANSIGNAL_FEED__ = {"generatedAt":"2026-10-20T09:26:21.232Z","sources":[{"id":"bills-official","label":"Bills.com","team":"bills","itemCount":10,"error":null},{"id":"espn-bills","label":"ESPN","team":"bills","itemCount":6,"error":null},{"id":"buffalo-rumblings","label":"Buffalo Rumblings","team":"bills","itemCount":10,"error":null},{"id":"pft-bills","label":"ProFootballTalk","team":"bills","itemCount":0,"error":null},{"id":"reddit-bills","label":"r/buffalobills","team":"bills","itemCount":0,"error":"HTTP 403"},{"id":"twobillsdrive","label":"TwoBillsDrive","team":"bills","itemCount":20,"error":null},{"id":"espn-sabres","label":"ESPN","team":"sabres","itemCount":6,"error":null},{"id":"die-by-the-blade","label":"Die By The Blade","team":"sabres","itemCount":10,"error":null},{"id":"buffalo-hockey-beat","label":"Buffalo Hockey Beat","team":"sabres","itemCount":10,"error":null},{"id":"sportsnet-nhl","label":"Sportsnet","team":"sabres","itemCount":0,"error":null},{"id":"cbs-nhl","label":"CBS Sports","team":"sabres","itemCount":1,"error":null},{"id":"espn-nhl-general","label":"ESPN NHL","team":"sabres","itemCount":0,"error":null},{"id":"reddit-sabres","label":"r/sabres","team":"sabres","itemCount":0,"error":"HTTP 403"},{"id":"hfboards-sabres","label":"HFBoards","team":"sabres","itemCount":0,"error":"HTTP 403"},{"id":"stars-and-stripes","label":"Stars and Stripes FC","team":"usmnt","itemCount":10,"error":null},{"id":"espn-soccer-usmnt","label":"ESPN Soccer","team":"usmnt","itemCount":0,"error":null},{"id":"cbs-soccer-usmnt","label":"CBS Sports","team":"usmnt","itemCount":1,"error":null},{"id":"reddit-ussoccer","label":"r/ussoccer","team":"usmnt","itemCount":0,"error":"HTTP 403"},{"id":"bandits-official","label":"Bandits.com","team":"bandits","itemCount":10,"error":null},{"id":"espn-nll","label":"ESPN NLL","team":"bandits","itemCount":0,"error":null}],"games":[{"team":"bills","state":"upcoming","headline":"Sun 1:00 PM","detail":"vs BAL"},{"team":"sabres","state":"final","headline":"Final · L 3-4","detail":"at MTL"},{"team":"bandits","state":"offday","headline":"Season over","detail":"1st round vs GA"},{"team":"usmnt","state":"final","headline":"Final · W 1-0","detail":"vs CAN"}],"stories":[{"id":"twobillsdrive::https://www.twobillsdrive.com/community/topic/267028-baldy-breakdown-walker-v-linderbaum/","team":"bills","title":"Baldy breakdown:  Walker v Linderbaum","summary":"With 27 seconds left - check out how many guys Walker draws lol","source":"TwoBillsDrive","sourceType":"forum","sourceCount":1,"publishedAt":"2026-10-20T03:02:36.000Z","link":"https://www.twobillsdrive.com/community/topic/267028-baldy-breakdown-walker-v-linderbaum/"},{"id":"twobillsdrive::https://www.twobillsdrive.com/community/topic/267027-a-few-thoughts-about-the-raiders-game-in-no-particular-order/","team":"bills","title":"A Few Thoughts about the Raiders Game, in no particular order","summary":"After last week's recap, I've decided I'm going to try something different. I think I've gotten so caught up in the overall trends of this team that I'm not really allowing myself to enjoy individual games anymore. Every bad play reminds me of something from three weeks ago, and every good play comes with a \"yeah, but will that work in the playoffs?\" So, for my own sanity, and probably yours too, I'm going to try to look at each game in a vacuum. I'll save my bigger-picture concerns for the final thought each week and hopefully find a little more enjoyment in watching football again.  With that being said, I missed the opening Bills drive (Thanks YouTubeTV), so apparently I also missed Brady burning two timeouts before the game even really got going. Maybe that was for the best.\n\n\n\n\t \n\n\n\n\t1 - Josh - I thought Josh played a pretty good game overall, even if it wasn't the type of performance we've become accustomed to seeing from him. The Raiders were getting consistent pressure and Josh wasn't running nearly as much as we've seen in previous games. Instead, he seemed more willing to take what was available underneath, especially early with Cook and Davis. I liked seeing that because I think it's something he needs to continue doing to make defenses respect the shorter throws.  There were still some classic Josh moments. The broken play where he found Palmer for 34 yards was ridiculous, and the pump fake where he managed to completely fool two defenders was almost comical. Then there's the little chest flip pass to Coleman for the touchdown. I have to remind myself not to take these plays for granted where he makes things look so effortless. I also appreciated seeing him put the ball at Shakir's chest on the WR screen touchdown instead of at his knees, which allowed Shakir to immediately take off. It's a small thing, but something I've complained about before. Overall, Josh didn't need to be Superman today, and that's a good thing.\n\n\n\n\t \n\n\n\n\t2 - Cook - I was really interested in seeing how Cook would respond after the fumbles last week, and I thought he had a really good game. You could clearly see him making an effort to secure the ball with both hands, almost to the point where it looked like he was thinking about it on every carry. But it didn't seem to take away from his running ability. He was making good cuts, finding holes, and continuing to show why he's such an important part of this offense. I also liked seeing him more involved in the passing game, especially on the drive where we went back ahead in the fourth quarter.  The one thing that drove me crazy was him running out of bounds with 2:40 left. What are you doing?! We could have taken that clock all the way down to the two-minute warning. I know he's trying to make a play, but situational awareness matters. Fortunately, we picked up the first down on the next play and it didn't cost us. Outside of that, this was exactly the type of bounce-back performance I wanted to see from him.\n\n\n\n\t \n\n\n\n\t3 - Coleman - I might have been more impressed with Coleman today than I've been in a while. The 22-yard catch against zone coverage was nice, but it was the contested catches that really stood out to me. The comeback route where he went up and fought for the ball was excellent. That's the type of play we've been waiting to consistently see from him. He also made another great catch late in the fourth quarter when we needed to keep the drive moving.  And of course, there's the touchdown on the ridiculous little flip pass from Josh. I don't know if Coleman has suddenly turned a corner or if this was just a good matchup for him, but he looked much more engaged and physical today. I've been pretty critical of him, so I'm more than happy to give him credit when he earns it. Hopefully this is something he can build on, because we desperately need another receiver who can make contested catches and give Josh a reliable target.\n\n\n\n\t \n\n\n\n\t4 - What do you want me to do\n\tTo do for you to see you through?\n\tFor this is all a dream we dreamed\n\tOne afternoon, long ago\n\n\n\n\t \n\n\n\n\t5 - Benford - I thought Benford had a really good game, especially considering he was being asked to cover Bowers for much of it. Bowers is one of the best tight ends in football and Benford was doing a great job taking him away. I believe Bowers didn't even record his first catch until there were about five minutes left in the third quarter. That's impressive. Which is why I was completely baffled when we stopped having Benford cover him. Suddenly Bowers is making big plays and the Raiders are moving right down the field. Then Benford gets back on him and immediately breaks up a pass. I don't understand why we would get away from something that was clearly working. Benford deserves a lot of credit because he showed exactly why he's one of the most important players on this defense. When he's able to take away the opposing team's best receiving threat, it makes everyone else's job easier.\n\n\n\n\t \n\n\n\n\t6 - Ty Johnson - I really liked seeing Ty involved early in this game. Between him and Kincaid, it felt like we were making a conscious effort to get some different players involved in the passing game. Ty is one of those guys who doesn't need a ton of touches to make an impact, but every time he gets the ball, I feel like there's an opportunity for something good to happen. I know Cook is going to get the majority of the work, and rightfully so, but I think Ty brings a different element to the offense. He's reliable as a receiver, has good speed, and can be a weapon in space. I would love to see him continue getting a handful of opportunities each game, especially when defenses are focusing so much attention on Cook. Sometimes the easiest way to help Josh is to give him another simple option who can turn a short pass into something more.\n\n\n\n\t \n\n\n\n\t7 - Walker - What a monster game from Walker. I feel like every time I looked up, he was either pushing someone into the backfield or blowing up a running play. The tackle where he basically piggybacked the running back into the ground was ridiculous. He was also getting the better of Linderbaum on multiple plays, which is no small accomplishment. I know defensive tackles don't always get the attention that edge rushers do, but Walker was impossible to miss today. We need guys who can consistently win their individual matchups and disrupt plays without having to bring extra pressure. Walker did exactly that. Great game from him.\n\n\n\n\t \n\n\n\n\t8 - The Defense - This was a strange defensive performance because there were stretches where I thought we looked really good, and others where the Raiders seemed to be able to move the ball whenever they wanted. The opening drive was frustrating with multiple third-down conversions and Bernard getting absolutely steamrolled on the touchdown. Then later, Bernard gets dragged for another few yards by a tight end. I'm not sure what's going on there, but those are plays he has to make.  I really do thing it's Shaq time coming out of the bye week.  On the positive side, IGB had two big pass breakups, including the third-and-goal stop. Bishop made a couple of really nice plays, including a great hit to break up a pass. Dorian Williams came away with the interception, even if Cousins basically threw it right at him. Gaines had a great play near the goal line, Groot batted down a pass late, and Kilgore made an excellent read to break up the third-down throw on the Raiders' final meaningful possession.  But the fourth quarter was frustrating. We had a 10-point lead and then completely stopped generating pressure. Bowers started getting open, the Raiders moved right down the field, and suddenly the game was tied. Even after we went back ahead, we gave up the deep shot to Tucker, who ran right past Kilgore and IGB. That's a play you simply can't allow in that situation. Fortunately, Shakir recovered the onside kick and we were able to end it.\n\n\n\n\t \n\n\n\n\t9 - Brady - I'm trying not to let this turn into another rant, but there were some things today that made absolutely no sense to me. First off, how do you burn two timeouts on the opening drive? I missed the drive itself, so maybe there's context I'm missing, but that's a pretty terrible way to start a game.  I did like seeing Josh take the underneath throws, getting Ty involved, and mixing things up on the drive where we retook the lead in the fourth quarter. But then there's the drive where we didn't run the ball a single time. Why?! Cook was running well, the Raiders were getting pressure on Josh, and we completely abandoned the run. We punt, and the Raiders go right down the field and tie the game. Then there's the holding call on Torrence that wiped out the fourth-down touchdown to Kincaid. I thought that was a terrible call, but it was another example of a promising drive being derailed.  Overall, I thought the offense did enough to win, but there were still stretches where we made things much harder than they needed to be.\n\n\n\n\t \n\n\n\n\t10 - Bigger Picture - Okay, so here's where I'm allowing myself to look beyond this particular game. We won, and there were some legitimately encouraging individual performances.  I think Bishop, IGB, Dorian, Shakir, Benford, and Coleman are all coming into form.  Josh was able to win without having to carry the entire offense. Cook bounced back from last week's fumbles. Coleman made some excellent catches. Benford showed he can take away an elite receiving threat. Walker was a monster. Those are all positives.  But I still can't ignore the fact that we blew a 10-point fourth-quarter lead against the Raiders and then almost did it again.  We continue to have stretches where the offense can't get out of its own way and our defense seems incapable of protecting a lead without making things interesting. The penalties (Hawes is becoming an issue with the false starts), situational mistakes, and inability to consistently pressure the quarterback are all things that we've seen before.  I also think it's worth remembering that this game could have gone very differently if we didn't make some of those late plays. Kilgore's breakup, the facemask penalty on the punt return, Bass making the field goal, and Shakir recovering the onside kick all mattered. We made enough plays to win, but it certainly wasn't comfortable. I'm going to stick with my new approach and try not to let those concerns take away from the good things we saw today. Every game doesn't need to be a statement about whether we're going to win the Super Bowl. Sometimes it's okay to just appreciate a win and move on.\n\n\n\n\t \n\n\n\n\t*I'm not giving CJGJ the satisfaction of a thought, but if we made changes at MLB and SS during the bye, I wouldn't be opposed.\n\n\n\n\t**I see that Adams is going to be out for 6-8 weeks in LA.  Think they'd want Palmer?\n\n\n\n\t \n\n\n\n\tOn to the bye week and a stress free Sunday where hopefully the Chiefs, Ravens, and Patriots find a way to lose.  I'm very curious to see what changes Leonhard has in store for this defense and hopefully we get to see Oliver and Moore back 100%.  \n\n\n\n\t \n\n\n\n\tGo Bills!!!!","source":"TwoBillsDrive","sourceType":"forum","sourceCount":1,"publishedAt":"2026-10-20T00:55:42.000Z","link":"https://www.twobillsdrive.com/community/topic/267027-a-few-thoughts-about-the-raiders-game-in-no-particular-order/"},{"id":"buffalo-rumblings::https://www.buffalorumblings.com/buffalo-bills-discussion/143354/san-francisco-49ers-vs-washington-commanders-week-6-mnf-fan-discussion","team":"bills","title":"San Francisco 49ers vs. Washington Commanders, Week 6 ‘MNF’ fan discussion","summary":"","source":"Buffalo Rumblings","sourceType":"blog","sourceCount":1,"publishedAt":"2026-10-19T23:57:12.000Z","link":"https://www.buffalorumblings.com/buffalo-bills-discussion/143354/san-francisco-49ers-vs-washington-commanders-week-6-mnf-fan-discussion"},{"id":"twobillsdrive::https://www.twobillsdrive.com/community/topic/267026-nfl-suspends-bills-cj-gardner-johnson-for-one-game-for-spitting/","team":"bills","title":"NFL suspends Bills' C.J. Gardner-Johnson for one game for spitting","summary":"The NFL has suspended Buffalo Bills safety C.J. Gardner-Johnson for one game without pay after cameras captured him spitting toward Las Vegas Raiders players on Sunday.\n\n\n\n\tThe league said in a statement that Gardner-Johnson violated Rule 12, Section 3, Article 1, which applies to \"any act which is contrary to the generally understood principles of sportsmanship.\"\n\n\n\n\tBarring an appeal, Gardner-Johnson will miss the Bills' Week 8 game against the Baltimore Ravens. Buffalo is on a bye this week. Any appeal would be heard by Derrick Brooks, Jordy Nelson, Ron Rivera or James Thrash, who are jointly appointed and paid by the NFL and the NFL Players Association.\n\n\n\n\tBills coach Joe Brady said Monday there'll be no further punishment for Gardner-Johnson beyond the league's suspension. Brady remained committed to Gardner-Johnson as a starter when he's eligible to return from suspension in Week 9.","source":"TwoBillsDrive","sourceType":"forum","sourceCount":2,"publishedAt":"2026-10-19T23:32:11.000Z","link":"https://www.twobillsdrive.com/community/topic/267026-nfl-suspends-bills-cj-gardner-johnson-for-one-game-for-spitting/"},{"id":"espn-bills::50193542","team":"bills","title":"49ers WR Mike Evans reps Bay Area with Curry jersey, leads NFL Week 6's arrivals","summary":"NFL stars continue to turn game-day arrivals into their own weekly fashion showcase.","source":"ESPN · Cameron Wolfe","sourceType":"league","sourceCount":1,"publishedAt":"2026-10-19T23:19:59Z","link":"https://www.espn.com/nfl/story/_/id/50193542/nfl-week-6-fashionable-arrivals"},{"id":"buffalo-hockey-beat::https://www.buffalohockeybeat.com/despite-rasmus-dahlin-injury-and-some-early-struggles-sabres-off-to-solid-start-in-playoff-spot/","team":"sabres","title":"Despite Rasmus Dahlin injury and some early struggles, Sabres off to solid start, in playoff spot","summary":"BUFFALO – Through nine games this season, the Sabres sport an underwhelming but intriguing 4-3-2 record.\nThe team that ended last season on a torrid 39-9-5 run has stumbled out of the gate a bit, often falling behind multiple goals before roaring back.\nIncredibly, the Sabres have held a lead just 60:32 this season, barely the equivalent of one game. Only two teams – the hapless Calgary Flames (39:21) and Los Angeles Kings (32:59) – ... Read the full article \nThe post Despite Rasmus Dahlin injury and some early struggles, Sabres off to solid start, in playoff spot first appeared on Buffalo Hockey Beat.","source":"Buffalo Hockey Beat","sourceType":"blog","sourceCount":1,"publishedAt":"2026-10-19T23:13:01.000Z","link":"https://www.buffalohockeybeat.com/despite-rasmus-dahlin-injury-and-some-early-struggles-sabres-off-to-solid-start-in-playoff-spot/"},{"id":"bills-official::https://www.buffalobills.com/news/bills-sign-cb-tre-davious-white-to-practice-squad-release-cb-a-j-woods","team":"bills","title":"Bills sign CB Tre'Davious White to practice squad, release CB A.J. Woods","summary":"White joins the Bills for his third stint, ninth year with the team.","source":"Bills.com","sourceType":"team","sourceCount":1,"publishedAt":"2026-10-19T21:59:26.000Z","link":"https://www.buffalobills.com/news/bills-sign-cb-tre-davious-white-to-practice-squad-release-cb-a-j-woods"},{"id":"bills-official::https://www.buffalobills.com/news/joe-brady-address-c-j-gardner-johnson-suspension-jim-leonhard-says-davison-igbinosun-has-earned-majority-of-the-snaps","team":"bills","title":"Joe Brady addresses C.J. Gardner-Johnson suspension, Jim Leonhard says Davison Igbinosun has earned \"majority of the snaps\"","summary":"The Buffalo Bills coaching staff met with the media Monday as the team heads into the bye week","source":"Bills.com","sourceType":"team","sourceCount":1,"publishedAt":"2026-10-19T21:31:57.000Z","link":"https://www.buffalobills.com/news/joe-brady-address-c-j-gardner-johnson-suspension-jim-leonhard-says-davison-igbinosun-has-earned-majority-of-the-snaps"},{"id":"buffalo-rumblings::https://www.buffalorumblings.com/buffalo-bills-news/143316/tredavious-white-signing-with-buffalo-bills-per-report","team":"bills","title":"Tre’Davious White signing with Buffalo Bills, per report","summary":"","source":"Buffalo Rumblings","sourceType":"blog","sourceCount":1,"publishedAt":"2026-10-19T21:17:36.000Z","link":"https://www.buffalorumblings.com/buffalo-bills-news/143316/tredavious-white-signing-with-buffalo-bills-per-report"},{"id":"twobillsdrive::https://www.twobillsdrive.com/community/topic/267024-if-you-think-we-have-it-bad-theres-always-the-rams/","team":"bills","title":"If you think we have it bad, there's always the Rams","summary":"I mean, holy crap.","source":"TwoBillsDrive","sourceType":"forum","sourceCount":1,"publishedAt":"2026-10-19T21:13:02.000Z","link":"https://www.twobillsdrive.com/community/topic/267024-if-you-think-we-have-it-bad-theres-always-the-rams/"},{"id":"twobillsdrive::https://www.twobillsdrive.com/community/topic/267022-tre-white-is-back/","team":"bills","title":"Tre White is back!","summary":"","source":"TwoBillsDrive","sourceType":"forum","sourceCount":1,"publishedAt":"2026-10-19T19:59:41.000Z","link":"https://www.twobillsdrive.com/community/topic/267022-tre-white-is-back/"},{"id":"buffalo-rumblings::https://www.buffalorumblings.com/buffalo-bills-news/143310/cj-gardner-johnson-suspended-one-game-for-spitting-incident-vs-raiders","team":"bills","title":"CJ Gardner-Johnson suspended one game for spitting incident vs. Raiders","summary":"","source":"Buffalo Rumblings","sourceType":"blog","sourceCount":1,"publishedAt":"2026-10-19T19:41:22.000Z","link":"https://www.buffalorumblings.com/buffalo-bills-news/143310/cj-gardner-johnson-suspended-one-game-for-spitting-incident-vs-raiders"},{"id":"buffalo-rumblings::https://www.buffalorumblings.com/buffalo-bills-analysis/143303/josh-allens-buffalo-bills-pressure-to-sack-rate-has-returned-to-normal-elite-level-figure","team":"bills","title":"Josh Allen’s pressure-to-sack rate has returned to normal elite-level figure","summary":"","source":"Buffalo Rumblings","sourceType":"blog","sourceCount":1,"publishedAt":"2026-10-19T17:31:35.000Z","link":"https://www.buffalorumblings.com/buffalo-bills-analysis/143303/josh-allens-buffalo-bills-pressure-to-sack-rate-has-returned-to-normal-elite-level-figure"},{"id":"twobillsdrive::https://www.twobillsdrive.com/community/topic/267020-josh-allens-hand-is-all-banged-up/","team":"bills","title":"Josh Allen's Hand Is All Banged Up.","summary":"I saw this on TV at the end of the broadcast when Josh was being interviewed.\n\n\n\n\tHis whole hand is bruised and purple. Including his wrist. That's his throwing hand.\n\n\n\n\tThat can't be helping. I saw somewhere somebody said last week that his hand was hurt and now I believe it!\n\n\n\n\tYou ever bang that little bone that sticks up on the outside of your wrist? I have and it hurts bad! And it takes a while to go away. Like weeks if you hit it hard enough.\n\n\n\n\t \n\n\n\n\tI'm glad we have a bye week!","source":"TwoBillsDrive","sourceType":"forum","sourceCount":1,"publishedAt":"2026-10-19T17:27:31.000Z","link":"https://www.twobillsdrive.com/community/topic/267020-josh-allens-hand-is-all-banged-up/"},{"id":"buffalo-hockey-beat::https://www.buffalohockeybeat.com/sabres-captain-rasmus-dahlin-jason-zucker-ready-to-return-from-injuries-justin-danforth-misses-practice/","team":"sabres","title":"Sabres captain Rasmus Dahlin, Jason Zucker ready to return from injuries; Justin Danforth misses practice","summary":"BUFFALO – Sabres captain Rasmus Dahlin, who has missed the last three games with an upper-body injury, returned to practice this morning and expects to play Wednesday against the Philadelphia Flyers.\n“I think I’ll be ready,” Dahlin said this afternoon in KeyBank Center.\nThe Sabres did well without Dahlin, their top defenseman, compiling a 1-0-2 record during their road trip.\n\nDahlin hasn’t played since shooting the puck and reaching for his lower back as he ... Read the full article \nThe post Sabres captain Rasmus Dahlin, Jason Zucker ready to return from injuries; Justin Danforth misses practice first appeared on Buffalo Hockey Beat.","source":"Buffalo Hockey Beat","sourceType":"blog","sourceCount":1,"publishedAt":"2026-10-19T17:20:01.000Z","link":"https://www.buffalohockeybeat.com/sabres-captain-rasmus-dahlin-jason-zucker-ready-to-return-from-injuries-justin-danforth-misses-practice/"},{"id":"die-by-the-blade::https://www.diebytheblade.com/buffalo-sabres-open-thread-wk-of-10-19/","team":"sabres","title":"Buffalo Sabres Open Thread, Wk of 10/19","summary":"Buffalo has a light week on the schedule before they embark on a West Coast trip, the first #SabresAfterDark outing for the season. They play the Flyers and then the Capitals, and to everyone’s great relief Philly just won their first game of the season so maybe they will not inevitably beat the Sabres on Wednesday on national TV. \n\n\n\nWed, Oct 21st, 7pm EST – Buffalo Sabres (4-3-2) vs Philadelphia Flyers (1-6-3)Sat, Oct 24th, 7pm EST – Buffalo Sabres at Washington Capitals (5-3-0)\n\n\n\n\n\n\n\nThe Amerks continued their win one, lose one record once again.\n\n\n\nWed, Oct 21st, 7:05pm EST – Rochester Americans vs Utica CometsFri, Oct 23rd, 7:00pm EST – Rochester Americans at Syracuse Crunch","source":"Die By The Blade","sourceType":"blog","sourceCount":1,"publishedAt":"2026-10-19T17:10:46.000Z","link":"https://www.diebytheblade.com/buffalo-sabres-open-thread-wk-of-10-19/"},{"id":"twobillsdrive::https://www.twobillsdrive.com/community/topic/267019-let%E2%80%99s-do-an-apples-to-apples-comparison-of-leonhard-vs-other-brand-new-dc%E2%80%99s/","team":"bills","title":"Let’s do an apples-to-apples comparison of Leonhard vs other brand new DC’s","summary":"There are 14 new defensive coordinators in the NFL this year, and 7 of them switched schemes (4-3 to 3-4 or vice versa). So the \"new scheme\" challenges aren’t unique to us. Half the new DCs in the league are dealing with the exact same thing.\n\n\n\n\t \n\n\n\n\tLeonhard ranks dead last among all 14. Every single other new DC has a better defense right now, including all 6 of the others who switched schemes as well. Nine of the 14 have actually improved their team's ranking from last year, some by 14 to 17 spots. And no defense has fallen off a cliff like we have (we've dropped 24 spots). The next worst drop is 14. We are 10 spots worse than the next worst collapse in the league.\n\n\n\n\t \n\n\n\n\tA recurring theme on the forum right now is that the players need more time, perhaps even a full year, to adjust to the new scheme. These other teams didn’t need that adjustment period. Something more is going on here.\n\n\n\n\t \n\n\n\n\tWhat I have seen\n\n\n\n\t \n\n\n\n\t- We have repeatedly found ourselves in second/third and short situations with our defensive backs lined up 10 yards off the line of scrimmage. That cushion lets the receiver walk forward 3 yards, turn around, and catch the ball for a first down. That's coaching.\n\n\n\n\t \n\n\n\n\t- On numerous occasions we have seen whole sections of our zone left wide open. That isn't talent either. I mean… it’s not like all of our players are too slow to get there and are trailing behind. That would be talent. It's that nobody even knows they're supposed to be there. That's coaching too. \n\n\n\n\t \n\n\n\n\t- How many times are we going to have 10 defensive players on the field versus the offense? Do the coaches not know how to count?\n\n\n\n\t \n\n\n\n\t- The stats will show that we ran more man coverage but what it doesn’t show is *when* we ran it. Times when I truly believe we should have (third and long press man, to give our d-line more time to get home), Leonhard instead dropped into a zone and we gave up a large play. \n\n\n\n\t \n\n\n\n\t- Even our QB pressure rate is worse. It was good for two weeks and then fell off a cliff. We are now 30th in the NFL in pressure %. \n\n\n\n\t \n\n\n\n\t- I frankly don’t care that our run defense is better. This is not 1982. Why should it matter that our run defense is stout when we are giving up 7 more points per game, and 93.7 more total yards per game, and 128.9 more passing yards, and our defense is generating fewer turnovers? Why should we care that we're stuffing the run when the very next play is a 25-yard pass? \n\n\n\n\t \n\n\n\n\tI really don’t know what the answer is, because they’re clearly not going to fire him after only six games. But I also don’t really see any evidence that this is going to get drastically better.\n\n\n\n\t \n\n\n\n\tThe only option I can realistically think of is to bring in Poyer. he is gone as a player, but I think he did a world of good for Bishop last year and he can probably continue reaping benefits for our defensive backs in general.","source":"TwoBillsDrive","sourceType":"forum","sourceCount":1,"publishedAt":"2026-10-19T17:00:10.000Z","link":"https://www.twobillsdrive.com/community/topic/267019-let%E2%80%99s-do-an-apples-to-apples-comparison-of-leonhard-vs-other-brand-new-dc%E2%80%99s/"},{"id":"stars-and-stripes::https://www.starsandstripesfc.com/usmnt-americans-abroad/46726/usmnt-weekend-roundup-heating-up-in-france","team":"usmnt","title":"USMNT weekend roundup: Heating up in France","summary":"","source":"Stars and Stripes FC","sourceType":"blog","sourceCount":1,"publishedAt":"2026-10-19T16:43:41.000Z","link":"https://www.starsandstripesfc.com/usmnt-americans-abroad/46726/usmnt-weekend-roundup-heating-up-in-france"},{"id":"espn-bills::50179373","team":"bills","title":"NFL Week 7 betting odds: Lines and totals for every game","summary":"A look at the odds, spreads, totals and FPI predictions for every NFL game in Week 7.","source":"ESPN · ESPN","sourceType":"league","sourceCount":1,"publishedAt":"2026-10-19T15:22:09Z","link":"https://www.espn.com/espn/betting/story/_/id/50179373/2026-nfl-week-7-schedule-odds-point-spreads-totals"},{"id":"buffalo-rumblings::https://www.buffalorumblings.com/buffalo-bills-analysis/143289/deone-walker-wrecked-tyler-linderbaum-in-buffalo-bills-win-over-raiders","team":"bills","title":"Deone Walker wrecked Tyler Linderbaum in Buffalo Bills win over Raiders","summary":"","source":"Buffalo Rumblings","sourceType":"blog","sourceCount":1,"publishedAt":"2026-10-19T14:44:27.000Z","link":"https://www.buffalorumblings.com/buffalo-bills-analysis/143289/deone-walker-wrecked-tyler-linderbaum-in-buffalo-bills-win-over-raiders"},{"id":"espn-bills::49545945","team":"bills","title":"How active NFL players continue to redefine all-time sack list","summary":"Myles Garrett's torrid pace up the all-time sack list paces active players making their moves among the greats.","source":"ESPN · Sarah Barshop","sourceType":"league","sourceCount":1,"publishedAt":"2026-10-19T14:23:56Z","link":"https://www.espn.com/nfl/story/_/id/49545945/all-sack-list-tracker-myles-garrett-von-miller-aaron-donald"},{"id":"espn-bills::50218025","team":"bills","title":"How a rookie saved the day for the Bills","summary":"Nick Suss breaks down a key defensive play from Jalon Kilgore in the fourth quarter that helped seal the Bills' win over the Raiders.","source":"ESPN","sourceType":"league","sourceCount":1,"publishedAt":"2026-10-19T13:47:03Z","link":"https://www.espn.com/video/clip/_/id/50218025/how-rookie-saved-day-bills"},{"id":"twobillsdrive::https://www.twobillsdrive.com/community/topic/267015-was-it-my-imagination-or-did-i-really-remember/","team":"bills","title":"Was it my imagination, or did I really remember...","summary":"...a Buffalo Bills defense where Trey White in his prime, while not quite a Revis, was pretty close to a shut down corner, and no one threw his way\n\n\n\n\t....where Poyer and Hyde seemed to be all over the field: whether double covering on deep passes, filling in run support, or those timely well conceived clean blitzes that would break up a drive\n\n\n\n\t...where Milano in his prime also seemed also be all over the field. His run support was fine, but he also never seemed to let quarterbacks escape and run wild...and the little release swing pass to the running back would get snuffed out for either a loss or very little gain.\n\n\n\n\tI haven't seen anything CLOSE to that with the current squad...but then again, maybe its just my imagination.","source":"TwoBillsDrive","sourceType":"forum","sourceCount":1,"publishedAt":"2026-10-19T13:40:10.000Z","link":"https://www.twobillsdrive.com/community/topic/267015-was-it-my-imagination-or-did-i-really-remember/"},{"id":"twobillsdrive::https://www.twobillsdrive.com/community/topic/267014-colts-fire-gm/","team":"bills","title":"Colts fire GM","summary":"Schefter just reported","source":"TwoBillsDrive","sourceType":"forum","sourceCount":1,"publishedAt":"2026-10-19T13:39:38.000Z","link":"https://www.twobillsdrive.com/community/topic/267014-colts-fire-gm/"},{"id":"twobillsdrive::https://www.twobillsdrive.com/community/topic/267013-trades-to-make-this-week/","team":"bills","title":"Trades to make this week","summary":"How feasible, from a contract standpoint, do you guys think it is for Beane to pull some trades to help the defense? I am thinking we might be able to get Zack Baun (who played for Leonhard at Wisconsin and someone like Budda Baker to help shore things up. We could cut CGJ and bench Bernard.","source":"TwoBillsDrive","sourceType":"forum","sourceCount":1,"publishedAt":"2026-10-19T13:32:52.000Z","link":"https://www.twobillsdrive.com/community/topic/267013-trades-to-make-this-week/"},{"id":"stars-and-stripes::https://www.starsandstripesfc.com/usmnt-americans-abroad/46618/usmnt-midweek-viewing-guide-europe-flurry-open-cup-final","team":"usmnt","title":"USMNT midweek viewing guide: Europe flurry, Open Cup final","summary":"","source":"Stars and Stripes FC","sourceType":"blog","sourceCount":1,"publishedAt":"2026-10-19T13:31:01.000Z","link":"https://www.starsandstripesfc.com/usmnt-americans-abroad/46618/usmnt-midweek-viewing-guide-europe-flurry-open-cup-final"},{"id":"espn-bills::50216042","team":"bills","title":"Bills Mafia road fans surprised, confused Josh Allen on Keon Coleman TD","summary":"Josh Allen's theatrical touchdown pass to Keon Coleman left him wondering who had the dominant fanbase at Allegiant Stadium.","source":"ESPN · Nick Suss","sourceType":"league","sourceCount":1,"publishedAt":"2026-10-19T13:02:00Z","link":"https://www.espn.com/nfl/story/_/id/50216042/josh-allen-bills-fan-alligient-stadium"},{"id":"buffalo-rumblings::https://www.buffalorumblings.com/buffalo-bills-news/143264/bills-news-recapping-win-over-raiders","team":"bills","title":"Bills news: Recapping win over Raiders","summary":"","source":"Buffalo Rumblings","sourceType":"blog","sourceCount":1,"publishedAt":"2026-10-19T12:37:45.000Z","link":"https://www.buffalorumblings.com/buffalo-bills-news/143264/bills-news-recapping-win-over-raiders"},{"id":"buffalo-rumblings::https://www.buffalorumblings.com/buffalo-bills-analysis/143263/takeaways-from-bills-win-over-raiders-josh-allen-james-cook","team":"bills","title":"Takeaways from Bills win over Raiders","summary":"","source":"Buffalo Rumblings","sourceType":"blog","sourceCount":1,"publishedAt":"2026-10-19T12:31:57.000Z","link":"https://www.buffalorumblings.com/buffalo-bills-analysis/143263/takeaways-from-bills-win-over-raiders-josh-allen-james-cook"},{"id":"twobillsdrive::https://www.twobillsdrive.com/community/topic/267010-a-part-of-improving-the-defensive-backfield-is-up-front/","team":"bills","title":"A part of improving the defensive backfield is up front.","summary":"The vaunted DL gets no pressure.  All the metrics for pass rush are bottom of the league. Pass rush rate, sacks, quick pressure rates all suck.  Walker and Rousseau individually have looked great at times.  Statue quarterbacks can just sit there until someone is open.  Pass rush and pass defense have a symbiotic relationship and neither is holding up their end right now.","source":"TwoBillsDrive","sourceType":"forum","sourceCount":1,"publishedAt":"2026-10-19T11:45:47.000Z","link":"https://www.twobillsdrive.com/community/topic/267010-a-part-of-improving-the-defensive-backfield-is-up-front/"},{"id":"espn-sabres::50216913","team":"sabres","title":"Canucks bring losing streak into home matchup against the Hurricanes","summary":"Carolina Hurricanes (7-2-1, in the Metropolitan Division) vs. Vancouver Canucks (2-7-1, in the Pacific Division)","source":"ESPN","sourceType":"league","sourceCount":1,"publishedAt":"2026-10-19T08:12:33Z","link":"http://www.espn.com/nhl/preview?gameId=401892548"},{"id":"twobillsdrive::https://www.twobillsdrive.com/community/topic/267004-ty-johnson-is-the-bills-kevin-faulk/","team":"bills","title":"Ty Johnson is the bills Kevin Faulk","summary":"We need this guy healthy and he could be such a critical guy in December and January \n\n\n\n\t \n\n\n\n\tHis blocking ability the trust Josh has in his block and release.. his screen ability.. and he can get more touches when we need them \n\n\n\n\t \n\n\n\n\tI just keep seeing ty Johnson being a guy who can get a bigger workload late in the season when we need it and I have so much faith in him\n\n\n\n\t \n\n\n\n\tTom Brady relied on faulk so much early in his career and he helped his development so much\n\n\n\n\t \n\n\n\n\tI know this board has people of all ages and lots of people will remember how terrific Kevin faulk was and some will not know the name....\n\n\n\n\t \n\n\n\n\tBut he was instrumental in three early Super bowls with the Patriots and a young Tom Brady and he was the ultimate leader and third down back in the backfield\n\n\n\n\t \n\n\n\n\tDoes not matter if ty Johnson gets the ball seven times in a game or if you only gets it three times \n\n\n\n\t \n\n\n\n\tHe makes the most of his opportunities and is a bull in a china shop running the ball.. looking to break things and inflict damage \n\n\n\n\t \n\n\n\n\tHe even wears the bull ring which I now endorse for my running backs because yeah I want a bull","source":"TwoBillsDrive","sourceType":"forum","sourceCount":1,"publishedAt":"2026-10-19T05:40:43.000Z","link":"https://www.twobillsdrive.com/community/topic/267004-ty-johnson-is-the-bills-kevin-faulk/"},{"id":"bills-official::https://www.buffalobills.com/news/top-things-we-learned-bills-vs-raiders-week-6","team":"bills","title":"Top things we learned Bills vs. Raiders | Week 6","summary":"Josh Allen's efficient performance to the defensive game plan against Brock Bowers and the team's ability to navigate a challenging stretch","source":"Bills.com","sourceType":"team","sourceCount":1,"publishedAt":"2026-10-19T03:37:42.000Z","link":"https://www.buffalobills.com/news/top-things-we-learned-bills-vs-raiders-week-6"},{"id":"bills-official::https://www.buffalobills.com/news/saw-our-guy-open-josh-allen-reflects-on-crazy-flip-pass-td-and-other-team-highlights-in-win-at-raiders","team":"bills","title":"'Saw our guy open' | Josh Allen reflects on crazy flip-pass TD and other team highlights in win at Raiders","summary":"Josh Allen's must-see touchdown, James Cook and Keon Coleman's continued excellence, and more","source":"Bills.com","sourceType":"team","sourceCount":1,"publishedAt":"2026-10-19T03:13:56.000Z","link":"https://www.buffalobills.com/news/saw-our-guy-open-josh-allen-reflects-on-crazy-flip-pass-td-and-other-team-highlights-in-win-at-raiders"},{"id":"espn-sabres::50216027","team":"sabres","title":"Sharangovich breaks late tie as the Flames end the Hurricanes' 7-game winning streak","summary":"— Yegor Sharangovich scored the go-ahead goal with 4:28 left and the Calgary Flames ended Carolina's seven-game winning streak, beating the defending champion Hurricanes 3-2 on Saturday night for their second victory of the season.","source":"ESPN","sourceType":"league","sourceCount":1,"publishedAt":"2026-10-19T03:07:33Z","link":"http://www.espn.com/nhl/recap?gameId=401892534"},{"id":"espn-sabres::50215967","team":"sabres","title":"Carolina Hurricanes vs. Calgary Flames: Game Highlights","summary":"Carolina Hurricanes vs. Calgary Flames: Game Highlights","source":"ESPN","sourceType":"league","sourceCount":1,"publishedAt":"2026-10-19T02:47:08Z","link":"https://www.espn.com/video/clip/_/id/50215967/game-highlights"},{"id":"buffalo-rumblings::https://www.buffalorumblings.com/buffalo-bills-history/143223/josh-allen-ties-jim-kellys-bills-passing-touchdown-record","team":"bills","title":"Josh Allen ties Jim Kelly’s Bills passing touchdown record","summary":"","source":"Buffalo Rumblings","sourceType":"blog","sourceCount":1,"publishedAt":"2026-10-19T01:18:41.000Z","link":"https://www.buffalorumblings.com/buffalo-bills-history/143223/josh-allen-ties-jim-kellys-bills-passing-touchdown-record"},{"id":"buffalo-rumblings::https://www.buffalorumblings.com/buffalo-bills-analysis/143222/bills-at-raiders-week-6-instant-game-analysis-buffalo-grinds-out-key-win","team":"bills","title":"Bills at Raiders Week 6 instant game analysis: Buffalo grinds out key win","summary":"","source":"Buffalo Rumblings","sourceType":"blog","sourceCount":1,"publishedAt":"2026-10-19T00:55:12.000Z","link":"https://www.buffalorumblings.com/buffalo-bills-analysis/143222/bills-at-raiders-week-6-instant-game-analysis-buffalo-grinds-out-key-win"},{"id":"buffalo-rumblings::https://www.buffalorumblings.com/buffalo-bills-analysis/143221/josh-allen-buffalo-bills-now-5-1-finding-ways-to-win-close-games","team":"bills","title":"Josh Allen, 5-1 Buffalo Bills continue finding ways to win close games","summary":"","source":"Buffalo Rumblings","sourceType":"blog","sourceCount":1,"publishedAt":"2026-10-19T00:47:06.000Z","link":"https://www.buffalorumblings.com/buffalo-bills-analysis/143221/josh-allen-buffalo-bills-now-5-1-finding-ways-to-win-close-games"},{"id":"twobillsdrive::https://www.twobillsdrive.com/community/topic/266996-3-up-3-down-rayduhs/","team":"bills","title":"3 up 3 down Rayduhs","summary":"UP\n\n\n\n\t \n\n\n\n\tKeon - clutch catches bad drop but I like the improvement\n\n\n\n\t \n\n\n\n\tBass - Money we needed him for every last point\n\n\n\n\t \n\n\n\n\tCJ Gardner Johnson - for doing the team a big favor and getting himself booted.... Hamlin is a better option at this point\n\n\n\n\t \n\n\n\n\tDown\n\n\n\n\t \n\n\n\n\tLeonlimp or Leonflaccid which ever you prefer no explanation needed this defense is a consistent embarrassment.  The look on 17s face tells the story they are completely incompetent \n\n\n\n\t \n\n\n\n\tBeane - he drafted, signed and orchestrated this defensive mess the problem was Beane all along\n\n\n\n\t \n\n\n\n\tSky Bell - again disinterested doesn't get open and takes penalties. He is a liability to this team\n\n\n\n\t \n\n\n\n\tHM - the invisible Chubb... another waste of a big contract for little production \n\n\n\n\t \n\n\n\n\tHOF - Palmer I am not even mentioning him anymore he is enshrined in the down HOF just sayin","source":"TwoBillsDrive","sourceType":"forum","sourceCount":1,"publishedAt":"2026-10-19T00:20:26.000Z","link":"https://www.twobillsdrive.com/community/topic/266996-3-up-3-down-rayduhs/"},{"id":"bills-official::https://www.buffalobills.com/news/bills-33-raiders-30-final-score-recap-highlights","team":"bills","title":"Bills 33, Raiders 30  | Final Score, recap + highlights","summary":"Buffalo finishes West Coast trip with another narrow victory","source":"Bills.com","sourceType":"team","sourceCount":1,"publishedAt":"2026-10-19T00:05:26.000Z","link":"https://www.buffalobills.com/news/bills-33-raiders-30-final-score-recap-highlights"},{"id":"twobillsdrive::https://www.twobillsdrive.com/community/topic/266995-cj-gardner-johnson-could-the-ejection-spell-the-end-for-him-in-buffalo-update-it-will-not/","team":"bills","title":"CJ Gardner-Johnson - Could the ejection spell the end for him in Buffalo? (Update: It will not)","summary":"A lot of fans have been asking for changes in the Secondary. Many mentioning Safety.\n\n\n\n\t \n\n\n\n\tBefore today, I had a hard time envisioning Cole Bishop being given up on so quickly or CJ Gardner-Johnson after just 5 games with the team. And although he's had a lot of bad, he did come up big with an Interception to put us in position for victory.\n\n\n\n\t \n\n\n\n\tHowever, the last game he looked as bad as he's looked for us. And today, he looked even worse. Then he was ejected for spitting on Brock Bowers.\n\n\n\n\t \n\n\n\n\tNow I'm considering - could the spit and ejection be the last straw for this team?\n\n\n\n\t \n\n\n\n\tIt wouldn't shock me if, us looking for ways to improve this defense, saw him getting ejected today as the last straw - and a good excuse to look for an upgrade.\n\n\n\n\t \n\n\n\n\tEdit: It appears, at least for now, CJGJ will remain with the team:","source":"TwoBillsDrive","sourceType":"forum","sourceCount":1,"publishedAt":"2026-10-19T00:05:04.000Z","link":"https://www.twobillsdrive.com/community/topic/266995-cj-gardner-johnson-could-the-ejection-spell-the-end-for-him-in-buffalo-update-it-will-not/"},{"id":"twobillsdrive::https://www.twobillsdrive.com/community/topic/266992-two-critical-leadership-moments-for-coach-brady/","team":"bills","title":"Two Critical Leadership Moments for Coach Brady","summary":"It may sound like hyperbole, but if we want to know what kind of leader Joe Brady is or wants to become, he has two absolutely critical leadership moments in the next 48 hours.\n\n\n\n\t \n\n\n\n\t#1. Leonard-fire, add a mentor, or stick with Leonard as DC?\n\n\n\n\t \n\n\n\n\tBrady needs to make this decision with Beane and now. With a bye week and now 6 weeks of data, Brady's decision will speak for the rest of this season and maybe all of next year and how he approaches leadership when his right-hand man is struggling.\n\n\n\n\t \n\n\n\n\t#2. What message about leadership, discipline, and accountability will Brady send to his team and to ownership regarding CJ Gardner-Johnson?\n\n\n\n\t \n\n\n\n\tThis is a paramount decision. It will let us know how Brady values in his players and optics of a team's culture.\n\n\n\n\t \n\n\n\n\tWill he support a league suspension, suspend or bench Johnson, look the other way but have a meeting? Will this speed up the pursuit of secondary help because Johnson may be more liability than asset to this D?\n\n\n\n\t \n\n\n\n\tWhat Brady does with these two decisions are as critical as anything else he does this season as the head coach of our Bills!","source":"TwoBillsDrive","sourceType":"forum","sourceCount":1,"publishedAt":"2026-10-18T23:48:25.000Z","link":"https://www.twobillsdrive.com/community/topic/266992-two-critical-leadership-moments-for-coach-brady/"},{"id":"bills-official::https://www.buffalobills.com/news/bills-issue-injury-update-on-te-dalton-kincaid","team":"bills","title":"Bills issue injury update on TE Dalton Kincaid","summary":"Kincaid left the game in the second half and went into the blue medical tent","source":"Bills.com","sourceType":"team","sourceCount":1,"publishedAt":"2026-10-18T22:56:27.000Z","link":"https://www.buffalobills.com/news/bills-issue-injury-update-on-te-dalton-kincaid"},{"id":"buffalo-hockey-beat::https://www.buffalohockeybeat.com/tage-thompson-taking-his-place-among-sabres-all-time-greats/","team":"sabres","title":"Tage Thompson taking his place among Sabres’ all-time greats","summary":"Early in his tenure in Buffalo, the idea of Tage Thompson someday taking his place among some of the Sabres’ all-time greats seemed ludicrous.\nIn 104 games over his first three years, he scored just 15 goals.\nBut Thompson matured rapidly after former Sabres coach Don Granato switched him from wing to center five years ago.\n\nToday, he ranks among the NHL’s elite scorers.\nIn 393 games since the beginning of the 2021-22 season, Thompson ... Read the full article \nThe post Tage Thompson taking his place among Sabres’ all-time greats first appeared on Buffalo Hockey Beat.","source":"Buffalo Hockey Beat","sourceType":"blog","sourceCount":1,"publishedAt":"2026-10-18T19:29:55.000Z","link":"https://www.buffalohockeybeat.com/tage-thompson-taking-his-place-among-sabres-all-time-greats/"},{"id":"twobillsdrive::https://www.twobillsdrive.com/community/topic/266988-gameday-101826-week-6-bills-at-raiders-425pm-post-game-thread/","team":"bills","title":"GAMEDAY 10/18/26 WEEK 6 Bills at Raiders 4:25pm post game THREAD","summary":"Bills 33 Raiders 30\n\n\n\n\t \n\n\n\n\tGo Bills!!!\n\n\n\n\t \n\n\n\n\tSee Y’all (I am a southern WNY’er transplant now) next week.","source":"TwoBillsDrive","sourceType":"forum","sourceCount":1,"publishedAt":"2026-10-18T19:10:24.000Z","link":"https://www.twobillsdrive.com/community/topic/266988-gameday-101826-week-6-bills-at-raiders-425pm-post-game-thread/"},{"id":"bills-official::https://www.buffalobills.com/news/dj-moore-ed-oliver-among-buffalo-bills-inactives-at-raiders","team":"bills","title":"DJ Moore, Ed Oliver among Buffalo Bills inactives at Raiders","summary":"The Buffalo Bills are listing five players as inactive for today's game against the Las Vegas Raiders.","source":"Bills.com","sourceType":"team","sourceCount":1,"publishedAt":"2026-10-18T18:54:20.000Z","link":"https://www.buffalobills.com/news/dj-moore-ed-oliver-among-buffalo-bills-inactives-at-raiders"},{"id":"bills-official::https://www.buffalobills.com/news/buffalo-bills-at-las-vegas-raiders-where-to-watch-stream-and-listen-week-6","team":"bills","title":"Buffalo Bills at Las Vegas Raiders | Where to watch, stream and listen | Week 6","summary":"TV Channel, Streaming and Radio for Bills at Raiders","source":"Bills.com","sourceType":"team","sourceCount":1,"publishedAt":"2026-10-18T14:00:00.000Z","link":"https://www.buffalobills.com/news/buffalo-bills-at-las-vegas-raiders-where-to-watch-stream-and-listen-week-6"},{"id":"twobillsdrive::https://www.twobillsdrive.com/community/topic/266983-week-six-2026-other-games-thread-no-bills-talk-please/","team":"bills","title":"Week Six 2026 - Other Games Thread (No Bills talk, please)","summary":"The final London game of the year. Jags started with a nice pass.\n\n\n\n\t \n\n\n\n\t(Sorry if this is a duplicate thread)","source":"TwoBillsDrive","sourceType":"forum","sourceCount":1,"publishedAt":"2026-10-18T13:37:47.000Z","link":"https://www.twobillsdrive.com/community/topic/266983-week-six-2026-other-games-thread-no-bills-talk-please/"},{"id":"espn-sabres::50201307","team":"sabres","title":"NHL Tonight: Previewing Blue Jackets-Wild, Hurricanes-Flames","summary":"Just two games on the schedule for hockey fans Sunday, but here's what you need to know.","source":"ESPN · ESPN Staff","sourceType":"league","sourceCount":1,"publishedAt":"2026-10-18T09:48:03Z","link":"https://www.espn.com/nhl/story/_/id/50201307/nhl-2026-27-tonight-games-schedule-matchups-stats-top-players-betting"},{"id":"espn-sabres::50208572","team":"sabres","title":"Carolina brings 7-game win streak into matchup against Calgary","summary":"Carolina Hurricanes (7-1-1, in the Metropolitan Division) vs. Calgary Flames (1-6, in the Pacific Division)","source":"ESPN","sourceType":"league","sourceCount":1,"publishedAt":"2026-10-18T08:11:35Z","link":"http://www.espn.com/nhl/preview?gameId=401892534"},{"id":"die-by-the-blade::https://www.diebytheblade.com/sabers-come-back-again-but-fall-to-canadiens-in-overtime/","team":"sabres","title":"Sabres come back again, but fall to Canadiens in overtime","summary":"Buffalo erases another two-goal deficit, but Cole Caufield ends the night just 54 seconds into overtime\n\n\n\nBoxscore\n\n\n\nScore: Buffalo Sabres 3-4 Montreal Canadiens (OT)\n\n\n\nShots: BUF 26-34 MTL\n\n\n\nBuffalo Sabres Goals: Norris 2 (Helenius), Quinn (Benson, Samuelsson) SHG, Thompson (Doan, Kulich)\n\n\n\nMontreal Canadiens Goals: Bolduc (Suzuki, Slafkovsky) PPG, Caufield (Slafkovsky, Carrier), Texier (Guhle, Carrier), Caufield (Unassisted) OT\n\n\n\nGoaltending: Luukkonen 30 saves (.882 SV%), Fowler 23 saves (.885 SV%)\n\n\n\nAdditional Stats: Buffalo won 36.8% of faceoffs, recorded 18 hits and blocked 17 shots.\n\n\n\nQuick Thoughts\n\n\n\nFirst Period – A Good Start Doesn’t Last\n\n\n\nFor once, the Buffalo Sabres didn’t have to spend the opening minutes digging themselves out of a hole. Josh Norris got Buffalo on the board first, taking a feed from Konsta Helenius and beating Jacob Fowler at 8:21 to give the Sabres a 1-0 lead. Unfortunately, that lead didn’t last long. Montreal answered just over three minutes later when Zachary Bolduc scored on the power play. Cole Caufield followed with another goal at 14:01, and Buffalo suddenly trailed 2-1 after the opening period. It has become a familiar problem for the Sabres this season. Even when they start well, they have struggled to control games and keep opponents from building momentum. Buffalo has shown it can battle back when things aren’t going its way, but it would be nice to see them play with a lead for a change.\n\n\n\nSecond Period – Jack Quinn to the Rescue\n\n\n\nBuffalo got worse early in the second period. Alexandre Texier scored at 7:39, extending Montreal’s lead to 3-1 and putting the Sabres in another two-goal hole. Sound familiar? Just two nights earlier, the Sabres trailed Toronto 4-2 entering the third period before rallying for an overtime win. Apparently, Buffalo tried the same approach against Montreal. Jack Quinn, who was outstanding against Toronto, continued his strong play by scoring a shorthanded goal at 9:52 of the second period. With assists from Zach Benson and Mattias Samuelsson, Quinn brought Buffalo back within one and gave the Sabres some much-needed life. Quinn has quickly become one of Buffalo’s most important offensive contributors. His chemistry with Benson has grown exponentially, and if he keeps this up, he will earn a nice payday. Whether it’s scoring, creating opportunities, or sparking the offense when the team desperately needs it, he keeps finding ways to make an impact. He even made a great backcheck to split up a two-on-one.\n\n\n\nThird Period – Here We Go Again\n\n\n\nAt this point, the Buffalo Sabres might actually prefer playing from behind. For the third straight game, Buffalo needed a comeback, and the Sabres delivered again. This time, Tage Thompson stepped up. At 10:12 of the third period, Thompson finished a play set up by Josh Doan and Jiri Kulich, beating Fowler to tie the game at three. Just like that, another two-goal deficit had disappeared. The Sabres had erased a 3-1 deficit against Montreal on Tuesday, came back from 4-2 down against Toronto on Thursday, and now had fought back from another 3-1 hole against the Canadiens. There is certainly something to be said about a team that refuses to quit. The Sabres have shown impressive resilience early this season, particularly in the third period. When they turn up the offensive pressure and start moving the puck with confidence, they can make life difficult for opponents. But this has become an almost ridiculous trend. Why does Buffalo need to be trailing by two goals before it starts playing its best hockey? The tying goal ensured the Sabres would collect at least one point, but another overtime appearance was waiting.\n\n\n\nOvertime – That Didn’t Take Long\n\n\n\nAfter needing overtime against Montreal on Tuesday and Toronto on Thursday, the Sabres were headed back to three-on-three hockey for the third straight game. Unfortunately, this overtime period didn’t last very long. Just 54 seconds into the extra frame, Cole Caufield scored his second goal of the night to give Montreal the 4-3 victory. And just like that, another dramatic Buffalo comeback ended with only one point to show for it. The Sabres have now played beyond regulation four times in their first nine games, including three consecutive overtime or shootout appearances. Buffalo might be getting comfortable playing extra hockey, but there is a difference between fighting back to earn a point and finishing the job.\n\n\n\nAt The Horn\n\n\n\nThe Buffalo Sabres are becoming one of the NHL’s most entertaining and frustrating teams to watch. On one hand, this team has shown it can overcome adversity. They don’t seem rattled when trailing by multiple goals, and their offensive players have consistently stepped up when needed. On the other hand, the Sabres are making things unnecessarily difficult for themselves. \n\n\n\nMontreal outshot Buffalo 34-26 and dominated in the faceoff circle, winning 63.2% of the draws. Ukko-Pekka Luukkonen made 30 saves to keep Buffalo within striking distance, but the Sabres once again struggled to play a complete game. \n\n\n\nThere are certainly positives to take away from the night. Quinn continued his offensive production, Thompson delivered another important goal, and Norris got Buffalo off to a promising start. But the larger issue remains. The Sabres have now erased two-goal deficits in three straight games. That speaks to their character, but it also raises serious questions about their ability to dictate games rather than constantly reacting to what their opponents do. \n\n\n\nLast season’s successful team found ways to win games without needing dramatic third-period comebacks every night. Buffalo needs to find that same consistency. It’s encouraging to know the Sabres can come back from almost anything. It’s considerably less encouraging that they keep putting themselves in those situations. With a 4-3-2 record in nine games, Buffalo has earned valuable points despite inconsistent performances. But overtime-loser points won’t be enough if the Sabres want to establish themselves as a legitimate contender in the Atlantic Division, and any point earned without Dahlin in the lineup is a good one.","source":"Die By The Blade","sourceType":"blog","sourceCount":1,"publishedAt":"2026-10-18T03:49:08.000Z","link":"https://www.diebytheblade.com/sabers-come-back-again-but-fall-to-canadiens-in-overtime/"},{"id":"espn-sabres::50206818","team":"sabres","title":"Ehlers’ power-play winner lifts Hurricanes past Jets 3-2 for 7th straight win","summary":"— Nikolaj Ehlers scored a power-play goal 6:43 into the third period to lift the Carolina Hurricanes to their seventh straight victory, 3-2 over the Winnipeg Jets on Saturday.","source":"ESPN","sourceType":"league","sourceCount":1,"publishedAt":"2026-10-18T02:02:27Z","link":"http://www.espn.com/nhl/recap?gameId=401892520"},{"id":"die-by-the-blade::https://www.diebytheblade.com/game-9-preview-open-thread-buffalo-sabres-at-montreal-canadiens/","team":"sabres","title":"Game #9 Preview & Open Thread: Buffalo Sabres at Montreal Canadiens","summary":"It’s Déjà Vu All Over Again With Buffalo Back at Bell Centre\n\n\n\nBuffalo Sabres (4-3-1) vs Montreal Canadiens (3-3-1)\n\n\n\nPuck Drop: 7:00 pm ET | Bell Centre – Montreal, Quebec\n\n\n\nTV: MSG-B, DAZN, ESPN+ (Hulu), NHL Center Ice, Prime Video\n\n\n\nRadio: WGR 550, Sirius XM (app)\n\n\n\nKnow Your Opponent\n\n\n\nMontreal Canadiens\n\n\n\nRecord: 3-3-1 | 7 PTS\n\n\n\nLast Game: Lost 5-4 to the Capitals\n\n\n\nDivision Ranking: 7th\n\n\n\nPP: 13.6% 27th (Sabres 11.1% 30th)\n\n\n\nPK: 80.0% 17th, 77.8% (Sabres 60.9% 30th)\n\n\n\nSeason Series: The Sabres are 0-0-1 against the Habs\n\n\n\n*knock knock* “Who’s there?” “It’s Déjà Vu”\n\n\n\n“Déjà Vu who?”\n\n\n\n*knock knock*\n\n\n\nWhat to Watch\n\n\n\n1. Do Not Adjust Your TV Sets\n\n\n\nThe Sabres once again return to the friendly confinds of Bell Centre in Montreal tonight with just four days and one game in Toronto between visits. Unusual scheduling to be sure. This second go-around will finish off the Maple Leaf sandwich with another slice of Montreal French bread.\n\n\n\nLast time out, Buffalo stormed back to steal a point in the standings before imploding in the shootout. The Sabres will need a better, more consistent effort in tonight’s matchup with the Habs to come out a winner. No more two-shot periods allowed!\n\n\n\nThe bad news for Buffalo is that Rasmus Dahlin has been ruled out again for today’s game against the Canadiens, Matthew Fairburn of The Athletic reports.\n\n\n\nHead coach Lindy Ruff said Thursday that Dahlin was 50/50 to play Saturday, but the 26-year-old won’t travel with the team to Montreal after all. However, Ruff said Friday that Dahlin is progressing, so it seems possible that he’ll be a candidate to return Wednesday against the Flyers. He remains listed as day-to-day for now.\n\n\n\n2. Four Jacks\n\n\n\nJack Quinn tied his career-best performance as a pro in Buffalo’s thrilling 5-4 overtime win over Toronto on Thursday night. The talented winger recorded two goals and two assists for a satisfying four-point night. He also showed some toughness after being confronted by Toronto’s Troy Stecher, handling himself well in a brief fight. To cap off the evening, Quinn set up Owen Power for the overtime winner. What a hand he played for the comeback victory.\n\n\n\nQuinn has looked noticeably more confident and effective on the ice this season, as things finally appear to be coming together for the fifth-year Sabre. He is tied for the team lead in both goals and points while averaging 19:20 of ice time per game. Lindy Ruff has repeatedly praised Quinn’s improved speed, growing confidence, and playmaking ability as he enters a crucial contract year. Along with Noah Östlund and Zach Benson, Quinn has helped form what has arguably been Buffalo’s best forward line this season.\n\n\n\nJack has been a major factor so far this year for Buffalo and Thursday’s performance was another encouraging sign of his development. The Sabres will need him to keep this momentum going if the team hopes to build on its recent success. If Quinn continues to play with this level of confidence and consistency, he could be in for a breakout season at just the right time.\n\n\n\n\n\n\n\n\nPhoto Credit: Buffalo Sabres\n\n\n\n\n3. Concussion Grenade\n\n\n\nOff to a slow start with just two points in eight games, Josh Norris now finds himself in concussion protocol. At this point, it almost feels like the Sabres’ injury report isn’t complete without him.\n\n\n\nNorris collided awkwardly with Oliver Ekman-Larsson during overtime in Toronto and did not return to finish the game. He’s listed as day-to-day and will likely miss at least a game or two. \n\n\n\nUPDATE Norris surprisingly practiced on Friday but the return-to-play process typically spans a minimum of 5 to 6 days (though actual return depends on symptom resolution).\n\n\n\nTyson Kozak can’t step into Norris’s spot as he has been sent home, but Jiri Kulich is the likely option if he’s feeling better. Kulich was recently sent back to Buffalo himself to be evaluated over concerns related to the blood clot he suffered last season. Fortunately, he checked out fine. Jiri has since returned to the team and is listed as a possibility to play tonight.\n\n\n\nIt’s been a disappointing start to the season for Norris. He opened the year playing top-line minutes but struggled to generate much offense. More recently, he’s been shuffled around the lineup and has seen mostly bottom-six duty. Now he’s dealing with another injury, although this one hopefully won’t keep him out for long. The Sabres are starting to get a little thin at forward.\n\n\n\nWith Norris, though, you can never be too comfortable. He could get injured opening his mail. \n\n\n\nSECOND UPDATE Norris practiced again this morning and is now a possibility to play tonight. I have to wonder how that’s possible, given the NHL’s mandates with concussions. Either his new evaluation determined he wasn’t actually suffering from a concussion, or something has changed rather quickly.\n\n\n\nProjected Lineups\n\n\n\nBuffalo Sabres\n\n\n\nForwards\n\n\n\nRyan McLeod – Tage Thompson – Josh Doan\n\n\n\nZach Benson – Noah Östlund – Jack Quinn\n\n\n\nPeyton Krebs – Jiri Kulich/Josh Norris? – Konsta Helenius\n\n\n\nJustin Danforth – Sam Carrick – Beck Malenstyn\n\n\n\nDefense\n\n\n\nMattias Samuelsson – Olen Zellweger\n\n\n\nOwen Power – Zach Metsa\n\n\n\nDennis Gilbert – Louis Crevier\n\n\n\nGoaltenders\n\n\n\nUkko-Pekka Luukkonen (likely to start)  Colten Ellis\n\n\n\nMontreal Canadiens\n\n\n\nForwards\n\n\n\nCole Caufield – Nick Suzuki – Juraj Slafkovsky\n\n\n\nChris Kreider – Alex Newhook – Josh Anderson\n\n\n\nZachary Bolduc – Phillip Danault – Alexandre Texier\n\n\n\nOwen Beck – Jake Evans – Kirby Dach\n\n\n\nDefense\n\n\n\nLane Hutson – Noah Dobson\n\n\n\nKaiden Guhle – Alexandre Carrier\n\n\n\nArber Xhekaj – David Reinbacher\n\n\n\nGoaltenders\n\n\n\nJacob Fowler (likely to start) Jakub Dobeš","source":"Die By The Blade","sourceType":"blog","sourceCount":1,"publishedAt":"2026-10-17T17:49:08.000Z","link":"https://www.diebytheblade.com/game-9-preview-open-thread-buffalo-sabres-at-montreal-canadiens/"},{"id":"buffalo-hockey-beat::https://www.buffalohockeybeat.com/following-recall-sabres-dennis-gilbert-scores-rare-goal-displays-tenacity/","team":"sabres","title":"Following recall, Sabres’ Dennis Gilbert scores rare goal, displays tenacity","summary":"TORONTO – Two nights earlier in Montreal, Buffalo Sabres coach Lindy Ruff pointed out, defenseman Dennis Gilbert had walked right down the slot and missed the net.\nIf Gilbert, 29, got another opportunity with the puck, he would surely score, right?\n“They say you give Dennis a second chance, and he’ll make the other team pay,” Ruff joked Thursday after Gilbert scored his first goal at any level in nearly three years.\n\nKidding aside, Gilbert’s ... Read the full article \nThe post Following recall, Sabres’ Dennis Gilbert scores rare goal, displays tenacity first appeared on Buffalo Hockey Beat.","source":"Buffalo Hockey Beat","sourceType":"blog","sourceCount":1,"publishedAt":"2026-10-17T05:21:36.000Z","link":"https://www.buffalohockeybeat.com/following-recall-sabres-dennis-gilbert-scores-rare-goal-displays-tenacity/"},{"id":"buffalo-hockey-beat::https://www.buffalohockeybeat.com/sabres-rasmus-dahlin-josh-norris-and-jiri-kulich-all-progressing-from-injuries-and-illness/","team":"sabres","title":"Sabres’ Rasmus Dahlin, Josh Norris and Jiri Kulich all progressing from injuries and illness","summary":"An upper-body injury will force Buffalo Sabres captain Rasmus Dahlin to miss his third straight game tonight, coach Lindy Ruff told reporters Friday in Montreal.\n“Progressing,” Ruff said of the defenseman’s status to reporters at the Bell Centre. “He’s feeling better today than yesterday.”\nAfter shooting the puck in Monday afternoon’s 5-3 win over the Florida Panthers, Dahlin reached for his lower back and left the game.\n\nThe Sabres received more good news Friday on ... Read the full article \nThe post Sabres’ Rasmus Dahlin, Josh Norris and Jiri Kulich all progressing from injuries and illness first appeared on Buffalo Hockey Beat.","source":"Buffalo Hockey Beat","sourceType":"blog","sourceCount":1,"publishedAt":"2026-10-17T05:04:50.000Z","link":"https://www.buffalohockeybeat.com/sabres-rasmus-dahlin-josh-norris-and-jiri-kulich-all-progressing-from-injuries-and-illness/"},{"id":"bills-official::https://www.buffalobills.com/news/buffalo-bills-injury-report-vs-raiders-week-6","team":"bills","title":"Buffalo Bills injury report vs. Raiders | Week 6","summary":"Five players will be questionable for Sunday's matchup against the Raiders.","source":"Bills.com","sourceType":"team","sourceCount":1,"publishedAt":"2026-10-16T21:46:02.000Z","link":"https://www.buffalobills.com/news/buffalo-bills-injury-report-vs-raiders-week-6"},{"id":"stars-and-stripes::https://www.starsandstripesfc.com/usmnt-news/46698/usmnt-weekend-viewing-guide-a-hard-start","team":"usmnt","title":"USMNT weekend viewing guide: A hard start","summary":"","source":"Stars and Stripes FC","sourceType":"blog","sourceCount":1,"publishedAt":"2026-10-16T19:52:50.000Z","link":"https://www.starsandstripesfc.com/usmnt-news/46698/usmnt-weekend-viewing-guide-a-hard-start"},{"id":"stars-and-stripes::https://www.starsandstripesfc.com/uswnt-news/46701/us-soccer-launches-arthur-m-blank-crest-cup-for-some-womens-soccer-teams","team":"usmnt","title":"US Soccer launches Arthur M. Blank Crest Cup for some women’s soccer teams","summary":"","source":"Stars and Stripes FC","sourceType":"blog","sourceCount":1,"publishedAt":"2026-10-16T16:28:10.000Z","link":"https://www.starsandstripesfc.com/uswnt-news/46701/us-soccer-launches-arthur-m-blank-crest-cup-for-some-womens-soccer-teams"},{"id":"buffalo-hockey-beat::https://www.buffalohockeybeat.com/jack-quinn-scores-fights-and-looks-like-star-in-sabres-wild-ot-win-buffalo-loses-jiri-kulich-josh-norris/","team":"sabres","title":"Jack Quinn scores, fights and looks like star in Sabres’ wild OT win; Buffalo loses Jiri Kulich, Josh Norris","summary":"TORONTO – It was only fitting that winger Jack Quinn capped the most dynamic outing in his NHL career by creating defenseman Owen Power’s overtime goal to cap another thrilling Sabres come-from-behind victory.\nOn a night Maple Leads winger Kirill Marchenko scored three times before the second period ended in Scotiabank Arena, Quinn was the best player on the ice in the Sabres’ 5-4 win, wreaking havoc from the get-go.\nQuinn scored two goals, hit ... Read the full article \nThe post Jack Quinn scores, fights and looks like star in Sabres’ wild OT win; Buffalo loses Jiri Kulich, Josh Norris first appeared on Buffalo Hockey Beat.","source":"Buffalo Hockey Beat","sourceType":"blog","sourceCount":1,"publishedAt":"2026-10-16T05:23:17.000Z","link":"https://www.buffalohockeybeat.com/jack-quinn-scores-fights-and-looks-like-star-in-sabres-wild-ot-win-buffalo-loses-jiri-kulich-josh-norris/"},{"id":"buffalo-hockey-beat::https://www.buffalohockeybeat.com/sabres-notes-owen-power-skating-big-minutes-becoming-elite-defenseman/","team":"sabres","title":"Sabres notes: Owen Power skating big minutes, becoming elite defenseman","summary":"TORONTO – In his five-year career, the Buffalo Sabres have never leaned more heavily on defenseman Owen Power.\nThrough seven games this season entering Thursday’s contest against the Maple Leafs, Power had averaged a whopping 26 minutes, 26 seconds of ice time.\nOnly five players – defensemen Zach Werenski, Thomas Chabot, Quinn Hughes and Lane Hutson – had skated more per outing.\n\nPower, of course, seemed destined for stardom when the Sabres drafted him first ... Read the full article \nThe post Sabres notes: Owen Power skating big minutes, becoming elite defenseman first appeared on Buffalo Hockey Beat.","source":"Buffalo Hockey Beat","sourceType":"blog","sourceCount":1,"publishedAt":"2026-10-16T05:03:55.000Z","link":"https://www.buffalohockeybeat.com/sabres-notes-owen-power-skating-big-minutes-becoming-elite-defenseman/"},{"id":"die-by-the-blade::https://www.diebytheblade.com/sabres-crunch-maple-leafs-stunning-comeback-quinn-power-overtime-winner/","team":"sabres","title":"Sabres crunch Leafs in stunning comeback","summary":"Buffalo pulled back another two-goal deficit in the third period for overtime win\n\n\n\nBoxscore\n\n\n\nScore: Buffalo Sabres 5-4 Toronto Maple Leafs OTShots: BUF 34-30 TOR\n\n\n\nBuffalo Sabres Goals: Jack Quinn 3 (Benson, Metsa), Quinn 4 (Östlund, Samuelsson), Gilbert 1 (Quinn, Benson), Samuelsson 2 (Thompson), Power 2 OT (Quinn, Östlund)Toronto Maple Leafs Goals: Matthews 6 (Roslovic), Marchenko 2 PPG (Tavares, Raddysh), Marchenko 3 (Tavares), Marchenko 4 (Sissons, Cowan)\n\n\n\nQuick Thoughts\n\n\n\nFirst Period – Pre-season Sabres\n\n\n\nWhat was that first period? Minus Jiri Kulich the entire team except one Jack Quinn seemed to be absent and anything the Leafs got came from Buffalo errors. \n\n\n\n\nJack Quinn is the beneficiary of a Toronto turnover after Zach Benson pressured Blankenburg, 1-1 #LetsGoBuffalo #Leafs pic.twitter.com/xKuELj0Cl0&mdash; Buffalo Hockey Moments (@SabresPlays) October 15, 2026\n\n\n\n\nOh, and if Ukko Pekka Luukkonen has heard the BUF-NYR-WPG triumvirate trade chatter, he certainly didn’t show it. \n\n\n\nWin a damned faceoff. The Leafs led the period 13-7 at the dot and led to a lot of their puck possession.\n\n\n\nRemember that whole thing about the Leafs having a plodding defense and that the Sabres should go up the ice vertically against them? Yeah they didn’t really, and the one time they did they scored. \n\n\n\nThe Sabres jumped on the Leafs to start, leading 7-2 on shots, but the period ended 15-8 to Toronto. \n\n\n\nThe Leafs got lucky with the the refs (hmmm) when they got an undeserving power play to close out the period after their own player high-sticked his teammate. The Leafs fifth-ranked power play ended the period 1 of 2 with a dozen second left in the man advantage. \n\n\n\n\nSam Carrick gets a two-minute penalty for having OEL high stick his own teammate pic.twitter.com/PdvV1cdkjn&mdash; Crossing Swords ⚔️ (@CrossSwordsPod) October 15, 2026\n\n\n\n\nSecond Period – Drought-era Sabres\n\n\n\nThe Sabres killed of the overlapping power play before Quinn continued his Leaf ownage, scoring his ninth goal in 15 games against Toronto, displaying his patience before McCabe bit and the Sabres forward blasted home over Bobrovsky’s shoulder. \n\n\n\nHe almost had a hattie a few minutes later when he waltzed through a static D but Bob refused to be embarrassed again. \n\n\n\n\nJack Quinn's 2nd goal of the game, 2-2 #LetsGoBuffalo #Leafs pic.twitter.com/zdINNj5aRq&mdash; Buffalo Hockey Moments (@SabresPlays) October 16, 2026\n\n\n\n\nOlen Zellweger decided not only was he going to replace Bowen Byram in the Sabres lineup, but he was going to take a further step and fill Rasmus Dahlin’s sizeable skates. He’s been very visible the last few games and was good again tonight. \n\n\n\nA full session of turnover-filled hockey in the neutral zone then ensued. As the Sabres then got lulled to sleep, Tavares won a board battle in the middle of the period, fed Marchenko and he beat UPL glove side for his second of the game to make it 3-2. \n\n\n\nQuinn hit the post and was active throughout the period again, and when Tage Thompson drew a penalty, Quinn even dropped the gloves against faux hard man Stecher. While he didn’t land a punch, he did wrestle his man to the ice and both drew five for fighting which alas hurt the Sabres more with their in-form top scorer taken off the ice. \n\n\n\nRemember when Knies was traded to the Blue Jackets on the eve of the season and then promptly scored twice against the Sabres on debut? Well the piece that went the other way was Marchenko and then with three minutes left Doan lost him in the blue paint he promptly got his hattrick to make it 4-2. \n\n\n\nWith just under two to play Rielly went off for hooking, but Benson took an immature penalty holding on to Sissons’s stick. But unlike that night when the Habs were not punished for that, Benson took a penalty and the power play was wasted. \n\n\n\nOnce again the Sabres were going to a third period having spotted their opponent a two-goal lead, despite having outshot the Leafs 13-11 in the period. \n\n\n\nThird Period – Division-winning Sabres\n\n\n\nThe Sabres have eight third period goals and it has been their best period by far. This one started with the same verve too with Buffalo humming around Bob’s net. \n\n\n\nPaul tripped Josh Norris into Tavares, sending the Leafs forward down the tunnel to the dressing room. \n\n\n\nTonight though, while Quinn was feeling it, who from the Sabres would step up and get a goal to add some pressure on the home side? Last season it was the defense, and once again tonight it was the dmen again. \n\n\n\nWell, Quinn found Dennis Gilbert at the blue line halfway through the period and the dman fired home over Bob’s pad to make it 4-3. That gave Quinn a very well-deserved Gordie Howe hattrick. Congrats to Buffalo boy and the much-loved Gibby for his first Sabres goal!\n\n\n\n\nDennis Gilbert gets on the board to make it 4-3 #LetsGoBuffalo #Leafs pic.twitter.com/M9CbWYHlaX&mdash; Buffalo Hockey Moments (@SabresPlays) October 16, 2026\n\n\n\n\nToronto were rocking on their heels and just two minutes later, Mattias Samuelsson joined the rush, took a feed from Tage and roofed a shot over Bob to make it 4-4 and the Scotiabank Arena was hushed. At that point the Sabres were outshooting the Leafs 10-1!\n\n\n\n\nMattias Samuelsson gets involved and ties the game, 4-4 #LetsGoBuffalo #Leafs pic.twitter.com/xcVa9T0p9Y&mdash; Buffalo Hockey Moments (@SabresPlays) October 16, 2026\n\n\n\n\nToronto belatedly woke up after that, but the rest of regulation time elapsed with little drama, 4-4 and advantage Sabres 11-4 for the period on shots. \n\n\n\nOvertime – He’s Got The Power!\n\n\n\nUnlike the OT in Quebec two nights ago when the Sabres barely had a sniff of the puck for five minutes, this one was more end-to-end. \n\n\n\nBenson had the puck on a three-on-one and then whiffed on his pass. Then Norris got clattered in the Leafs defensive zone and Power wisely held on to the puck to allow the forward to hobble off the ice. They went straight up the guy after that with Östlund feeding up Power who then fired off a howitzer to beat Bobrovsky for another OT winner!\n\n\n\n\nOwen Power overtime winner, 5-4 #LetsGoBuffalo #Leafs pic.twitter.com/luzb3aqI1C&mdash; Buffalo Hockey Moments (@SabresPlays) October 16, 2026\n\n\n\n\nMake that three straight goals scored by defensemen tonight when the forwards minus Quinn were all sputtering. \n\n\n\nAt The Horn\n\n\n\nThe Sabres simply cannot keep spotting teams leads going into the third period and assuming they can just reel them back in, especially against offensively endowed teams like the Leafs and and even more so when they are still without captain Rasmus Dahlin. \n\n\n\nLuukkonen wasn’t bad tonight, but as he has so often this season, he saved shots he shouldn’t have, and was beaten by shots he should have saved, ending the night on a deficit of -1.03 once again in the Goals Saved Above Average. \n\n\n\n\nNHL Game Score Impact Card for Buffalo Sabres on 2026-10-15: pic.twitter.com/xPRNYvTxD9&mdash; HockeyStatCards (@hockeystatcards) October 16, 2026","source":"Die By The Blade","sourceType":"blog","sourceCount":1,"publishedAt":"2026-10-16T02:09:45.000Z","link":"https://www.diebytheblade.com/sabres-crunch-maple-leafs-stunning-comeback-quinn-power-overtime-winner/"},{"id":"die-by-the-blade::https://www.diebytheblade.com/game-8-preview-open-thread-sabres-at-maple-leafs/","team":"sabres","title":"Game #8 Preview & Open Thread: Sabres at Maple Leafs","summary":"Buffalo renews rivalry with Toronto\n\n\n\nBuffalo Sabres (3-3-1) at Toronto Maple Leafs (3-3-1)\n\n\n\nPuck Drop: 7 p.m. ET | Scotiabank Arena, Toronto\n\n\n\nTV: MSG-B, TSN4, DAZN, ESPN+, Fubo\n\n\n\nRadio: WGR 550, Sirius XM (app)\n\n\n\nKnow Your Opponent\n\n\n\nToronto Maple Leafs\n\n\n\nRecord: 3-3-1 | 7 PTS\n\n\n\nLast Game: 5-4 loss at Utah\n\n\n\nDivision Ranking: 6th\n\n\n\nPP: 5th, 29.2% [Sabres: 30th, 11.1%]\n\n\n\nPK: 1st, 95.8% [Sabres: 30th, 60.9%]\n\n\n\nSeason Series: Sabres 3-0-1 vs. Maple Leafs in 2025-26 season\n\n\n\nWhat to Watch\n\n\n\n1. Zellweger shining in Dahlin’s absence\n\n\n\nOlen Zellweger already had big shoes to fill when he was acquired from Anaheim this offseason, and when Sabres captain Rasmus Dahlin went down with an injury in Monday’s win over the Panthers, it forced the 23-year-old into an even bigger role.\n\n\n\nFortunately for Buffalo, he’s certainly looked the part so far.\n\n\n\nZellweger had two goals and finished with a career-high 25:49 of ice time in Tuesday’s shootout loss in Montreal, and led Sabres skaters in shots on goal for the second consecutive game. With Dahlin out again against the Maple Leafs, another standout performance from Zellweger could go a long way toward securing two points in a divisional matchup.\n\n\n\n2. Luukkonen finding his game?\n\n\n\nSabres coach Lindy Ruff kept it suffice on Ukko-Pekka Luukkonen’s performance following Tuesday’s game: “Our goalie got us a point.”\n\n\n\nLuukkonen stopped 35-of-38 shots against the Canadiens, including a crucial late save with 3 seconds remaining in regulation that secured the Sabres a point. He also finished with a positive goals saved above expected for the second consecutive game, according to Hockeystats.com, following a strong relief appearance against Florida. Despite an abnormally poor showing in the shootout, it seemed like the Finn was finally beginning to get into a rhythm in the crease.\n\n\n\nThe Sabres will look to Luukkonen again to start on Thursday, but he faces a bogey team in the Maple Leafs. The 27-year-old is 0-5-2 in eight appearances against Toronto in his career.\n\n\n\n3. Early elation to frustration\n\n\n\nThe Sabres were a remarkable 36-6-2 when scoring first last season, a conversion rate that played a major factor in sending the franchise back to the playoffs, but it’s been tough sledding in that category to start this campaign.\n\n\n\nBuffalo is 1-2-1 this season when tallying the first goal, a worrying trend albeit one with a small sample size. On top of that, in all four games the Sabres have scored first, they have failed to get the next goal and been outscored 7-3 in the second period.\n\n\n\nShould the Sabres score first for the fifth time this season against Toronto, following up on that early momentum would be a welcome sight.\n\n\n\nInjury Notes\n\n\n\nIn addition to being without Dahlin on Thursday, the Sabres will also be down Tyson Kozak, who is dealing with an upper-body injury. Ruff said Wednesday that goalie Alex Lyon suffered a setback in his recovery from a shoulder injury, meaning he’ll be off the ice for a few days after returning to practice last week.\n\n\n\nToronto will be without defenseman Chris Tanev, who is week-to-week with an upper-body injury suffered in the Maple Leafs’ win over Colorado on Sunday.\n\n\n\nProjected Lineups\n\n\n\nBuffalo Sabres\n\n\n\nForwards\n\n\n\nPeyton Krebs – Tage Thompson – Josh DoanZach Benson – Noah Ostlund – Jack QuinnJiri Kulich – Ryan McLeod – Konsta HeleniusBeck Malenstyn – Josh Norris – Justin Danforth\n\n\n\nDefense\n\n\n\nMattias Samuelsson – Olen ZellwegerOwen Power – Zach MetsaDennis Gilbert – Louis Crevier\n\n\n\nGoaltenders\n\n\n\nUkko-Pekka Luukkonen (projected starter), Colten Ellis\n\n\n\nToronto Maple Leafs\n\n\n\nForwards\n\n\n\nKirill Marchenko – Auston Matthews – Jack RoslovicEaston Cowan – John Tavares – William NylanderGavin McKenna – Nick Paul – Colton SissonsBrandon Duhaime – Teddy Blueger\n\n\n\nDefense\n\n\n\nJake McCabe – Darren RaddyshMorgan Rielly – Troy StecherOliver Ekman-Larsson – Nick BlankenburgMarshall Rifai\n\n\n\nGoaltenders\n\n\n\nSergei Bobrovsky (projected starter), Anthony Stolarz","source":"Die By The Blade","sourceType":"blog","sourceCount":1,"publishedAt":"2026-10-15T21:16:22.000Z","link":"https://www.diebytheblade.com/game-8-preview-open-thread-sabres-at-maple-leafs/"},{"id":"twobillsdrive::https://www.twobillsdrive.com/community/topic/266954-jalen-hurts-out-indefinitely-for-eagles-blood-clot/","team":"bills","title":"Jalen Hurts out indefinitely for Eagles (blood clot)","summary":"Horrible season in Philadelphia. Already 2-3 and now missing Hurts. Barkley is banged up. Could they end up sellers at the deadline? You know Howie likes his trades. I'd at least ask about Baun or Trotter.","source":"TwoBillsDrive","sourceType":"forum","sourceCount":1,"publishedAt":"2026-10-15T17:50:05.000Z","link":"https://www.twobillsdrive.com/community/topic/266954-jalen-hurts-out-indefinitely-for-eagles-blood-clot/"},{"id":"buffalo-hockey-beat::https://www.buffalohockeybeat.com/sabres-goalie-alex-lyon-endures-injury-setback-rasmus-dahlin-jason-zucker-closer-to-playing/","team":"sabres","title":"Sabres goalie Alex Lyon endures injury setback; Rasmus Dahlin, Jason Zucker closer to playing","summary":"TORONTO – Had he kept recovering from the left shoulder injury he suffered in the preseason, Sabres coach Lindy Ruff said goalie Alex Lyon would’ve made his season debut Tuesday in Montreal.\nInstead, as his teammates lost a 4-3 shootout to the Canadiens, Lyon, having suffered a setback in practice, was back in Buffalo.\n“Now we’ll just see with rehab and stuff where he ends up,” Ruff said this morning in Scotiabank Arena.\n\nRuff said ... Read the full article \nThe post Sabres goalie Alex Lyon endures injury setback; Rasmus Dahlin, Jason Zucker closer to playing first appeared on Buffalo Hockey Beat.","source":"Buffalo Hockey Beat","sourceType":"blog","sourceCount":1,"publishedAt":"2026-10-15T17:02:45.000Z","link":"https://www.buffalohockeybeat.com/sabres-goalie-alex-lyon-endures-injury-setback-rasmus-dahlin-jason-zucker-closer-to-playing/"},{"id":"cbs-soccer-usmnt::https://www.cbssports.com/soccer/news/el-salvador-coach-strips-perks-publicly-before-facing-uswnt/","team":"usmnt","title":"El Salvador coach threatens to remove players from squad, strips perks a month before facing USWNT","summary":"Eric Acuna called out his own squad and revoked privileges after back-to-back friendly losses, putting La Selecta in turmoil ahead of a Concacaf W Championship quarterfinal with the USWNT","source":"CBS Sports","sourceType":"league","sourceCount":1,"publishedAt":"2026-10-15T16:43:31.000Z","link":"https://www.cbssports.com/soccer/news/el-salvador-coach-strips-perks-publicly-before-facing-uswnt/"},{"id":"stars-and-stripes::https://www.starsandstripesfc.com/social-video-twitter/46690/usa-soccercast-episode-201-breaking-down-the-international-windows","team":"usmnt","title":"USA Soccercast, Episode 201: Breaking down the international windows","summary":"","source":"Stars and Stripes FC","sourceType":"blog","sourceCount":1,"publishedAt":"2026-10-15T15:05:51.000Z","link":"https://www.starsandstripesfc.com/social-video-twitter/46690/usa-soccercast-episode-201-breaking-down-the-international-windows"},{"id":"buffalo-hockey-beat::https://www.buffalohockeybeat.com/following-trade-speedy-olen-zellweger-making-fast-impact-with-sabres/","team":"sabres","title":"Following trade, speedy Olen Zellweger making fast impact with Sabres","summary":"TORONTO – In his first game subbing for injured Buffalo Sabres captain Rasmus Dahlin, Olen Zellweger performed splendidly, enjoying perhaps his best night in the NHL.\nSkating alongside defenseman Mattias Samuelsson for much of Tuesday’s 4-3 shootout loss to the Montreal Canadiens, Zellweger set career highs by scoring two goals and playing 25 minutes, 49 seconds.\nNo one, of course, can truly replace Dahlin, one of the NHL’s most dynamic defensemen, as he recovers from ... Read the full article \nThe post Following trade, speedy Olen Zellweger making fast impact with Sabres first appeared on Buffalo Hockey Beat.","source":"Buffalo Hockey Beat","sourceType":"blog","sourceCount":1,"publishedAt":"2026-10-15T05:36:19.000Z","link":"https://www.buffalohockeybeat.com/following-trade-speedy-olen-zellweger-making-fast-impact-with-sabres/"},{"id":"stars-and-stripes::https://www.starsandstripesfc.com/athletes-in-focus/46609/ssfc-spotlight-julian-eyestone-grinding-in-league-two","team":"usmnt","title":"SSFC Spotlight: Julian Eyestone grinding in League Two","summary":"","source":"Stars and Stripes FC","sourceType":"blog","sourceCount":1,"publishedAt":"2026-10-15T03:59:07.000Z","link":"https://www.starsandstripesfc.com/athletes-in-focus/46609/ssfc-spotlight-julian-eyestone-grinding-in-league-two"},{"id":"bandits-official::https://bandits.com/jay-thorimbert-signs-1-day-contract-to-retire-with-bandits/","team":"bandits","title":"Jay Thorimbert signs 1-day contract to retire with Bandits","summary":"The Buffalo Bandits have signed Jay Thorimbert to a one-day contract for the purpose of retiring a Bandit.  Thorimbert, an 18-year NLL veteran, spent seven seasons in Buffalo – including the 2007-08 NLL Cup-winning campaign – and was drafted by the organization in 2006.   “I was drafted by Buffalo in 2006 and spent seven years with the organization, including being part of the […]","source":"Bandits.com","sourceType":"team","sourceCount":1,"publishedAt":"2026-10-14T17:57:59.000Z","link":"https://bandits.com/jay-thorimbert-signs-1-day-contract-to-retire-with-bandits/"},{"id":"bandits-official::https://bandits.com/bandits-sign-shognosh-to-3-year-deal/","team":"bandits","title":"Bandits sign Shognosh to 3-year deal","summary":"The Buffalo Bandits today announced the team has signed goaltender Waukiigan Shognosh to a three-year contract, pending league approval.   Shognosh (6’2”, 180 lbs., 2/7/20007) was selected in the first round (14th overall) of the 2025 NLL Entry Draft. He was named the Ontario Junior Lacross League Goaltender of the Year in 2025 after posting a […]","source":"Bandits.com","sourceType":"team","sourceCount":1,"publishedAt":"2026-10-14T17:56:59.000Z","link":"https://bandits.com/bandits-sign-shognosh-to-3-year-deal/"},{"id":"bandits-official::https://bandits.com/bandits-sign-gonsiorek-young/","team":"bandits","title":"Bandits sign Gonsiorek, Young","summary":"The Buffalo Bandits today announced the team has signed defenseman Kyle Gonsiorek to a three-year contract and transition player Dalton Young to a one-year contract. Both deals are pending league approval. Young (6’0”, 195 lbs., 1/31/2001) spent the last two seasons playing for the Philadelphia Wings after they drafted him in the third round (45th overall) of the 2023 NLL Entry Draft. He ranked fifth among Wings players […]","source":"Bandits.com","sourceType":"team","sourceCount":1,"publishedAt":"2026-10-14T17:53:59.000Z","link":"https://bandits.com/bandits-sign-gonsiorek-young/"},{"id":"bandits-official::https://bandits.com/bandits-sign-bowen-to-3-year-contract/","team":"bandits","title":"Bandits sign Bowen to 3-year contract","summary":"The Buffalo Bandits today announced the team has signed transition player Dante Bowen to a three-year contract, pending league approval. Bowen (6’1”, 205 lbs., 2/7/2003) spent the 2026 season at Syracuse University, where he recorded four assists, 16 ground balls and 14 caused turnovers in 19 games. His 14 caused turnovers ranked third among all Syracuse players. Following the season, Bowen earned USA Lacrosse Honorable Mention All-America recognition as a short-stick […]","source":"Bandits.com","sourceType":"team","sourceCount":1,"publishedAt":"2026-10-14T17:52:59.000Z","link":"https://bandits.com/bandits-sign-bowen-to-3-year-contract/"},{"id":"bandits-official::https://bandits.com/bandits-sign-4-players-to-contracts/","team":"bandits","title":"Bandits sign 4 players to contracts","summary":"The Buffalo Bandits today announced the team has signed forward Travis Longboat and transition player Thomas Whitty to one-year contracts. Additionally, the team has signed defenseman Jimmy Freehill and forward Owen Rice to three-year contracts. All four contracts are pending league approval. Whitty (6’1”, 185 lbs., 1/23/1999) has registered 23 points (1+22) and 336 loose-ball […]","source":"Bandits.com","sourceType":"team","sourceCount":1,"publishedAt":"2026-10-14T17:51:59.000Z","link":"https://bandits.com/bandits-sign-4-players-to-contracts/"},{"id":"bandits-official::https://bandits.com/bandits-sign-dawson-cortes/","team":"bandits","title":"Bandits sign Dawson, Cortes","summary":"The Buffalo Bandits today announced the team has signed defenseman Paul Dawson to a one-year contract and defenseman Raymond Cortes to a three-year contract. Both contracts are pending league approval. Dawson (6’5”, 237 lbs., 9/16/1985) will return for his third season with the Bandits and 20th season in the NLL. He tallied two points (0+2), […]","source":"Bandits.com","sourceType":"team","sourceCount":1,"publishedAt":"2026-10-14T17:50:59.000Z","link":"https://bandits.com/bandits-sign-dawson-cortes/"},{"id":"bandits-official::https://bandits.com/bandits-sign-andrews-booth-scanlan/","team":"bandits","title":"Bandits sign Andrews, Booth, Scanlan","summary":"The Buffalo Bandits today announced the team has signed forward Clay Scanlan to a two-year contract. Additionally, the team has signed transition player Ryan Andrews and forward Arrow Booth to three-year contracts. All three deals are pending league approval. Scanlan (5’10”, 175 lbs., 9/22/2001) set new career highs in games played (17), goals (11), assists (11), points (22) and loose balls (60) in his sophomore season in the NLL. Over his two seasons with the Bandits, he has recorded 38 points (20+18) and […]","source":"Bandits.com","sourceType":"team","sourceCount":1,"publishedAt":"2026-10-14T17:49:59.000Z","link":"https://bandits.com/bandits-sign-andrews-booth-scanlan/"},{"id":"die-by-the-blade::https://www.diebytheblade.com/buffalo-sabres-open-thread-wk-of-10-12/","team":"sabres","title":"Buffalo Sabres Open Thread, Wk of 10/12","summary":"Busy four-game week, all four are divisional clashes. \n\n\n\nMon, Oct 12th, 1pm EST – Buffalo Sabres vs Florida PanthersTue, Oct 13th, 6:30pm EST – Buffalo Sabres at Montreal Canadiens Thu, Oct 15th, 7pm EST – Buffalo Sabres at Toronto Maple LeafsSat, Oct 17th, 7pm EST – Buffalo Sabres at Montreal Canadiens \n\n\n\n\n\n\n\nThe Amerks had a big 7-1 win at home, but then a narrow 2-1 loss on the road too.\n\n\n\nFri, Oct 16th, 7:05pm EST – Rochester Americans at Hamilton HammersSat, Oct 17th, 5:00pm ET – Rochester Americans at Syracuse Crunch\n\n\n\nImage courtesy Buffalo Sabres","source":"Die By The Blade","sourceType":"blog","sourceCount":1,"publishedAt":"2026-10-14T16:56:52.000Z","link":"https://www.diebytheblade.com/buffalo-sabres-open-thread-wk-of-10-12/"},{"id":"stars-and-stripes::https://www.starsandstripesfc.com/uswnt-news/46666/uswnt-vs-spain-what-we-learned-still-looking-for-the-right-pieces","team":"usmnt","title":"USWNT vs. Spain – What we learned: still looking for the right pieces","summary":"","source":"Stars and Stripes FC","sourceType":"blog","sourceCount":1,"publishedAt":"2026-10-14T16:38:46.000Z","link":"https://www.starsandstripesfc.com/uswnt-news/46666/uswnt-vs-spain-what-we-learned-still-looking-for-the-right-pieces"},{"id":"twobillsdrive::https://www.twobillsdrive.com/community/topic/266930-what-are-the-tbd-thoughts-on-keon-coleman/","team":"bills","title":"What are the TBD thoughts on Keon Coleman","summary":"Well?\n\n\n\n\t \n\n\n\n\tweek 5 is in the books and our Bills are 4-1\n\n\n\n\t \n\n\n\n\twhy do I pick Keon Coleman to point out?\n\n\n\n\t \n\n\n\n\tterry Pegula and Brandon Beane saying “well we didn’t want him” after the firing of McDermott - throwing a starter under the bus and a young talent - terrible PR and Management there.\n\n\n\n\t \n\n\n\n\tso?  Where’s he at?\n\n\n\n\t \n\n\n\n\t15 receptions on 18 targets\n\n\n\n\t224 yards\n\n\n\n\t2 TDs\n\n\n\n\t \n\n\n\n\twhats funny is the last two games when no one else has showed up - Keon made TD receptions in the last minutes of regulation \n\n\n\n\t \n\n\n\n\tbeautiful one against NE (incredible game all together for him)\n\n\n\n\t \n\n\n\n\tthen this week \n\n\n\n\tdrawing a HUGE penalty \n\n\n\n\tthen a great job on his route for the TD (play design there was excellent)\n\n\n\n\t \n\n\n\n\tpost this as receipts \n\n\n\n\tpwrsonally point Coleman has 900 range yards 10 tds - continue to make some big plays down by the goal line - use his body in moments like this week.\n\n\n\n\t \n\n\n\n\tthem watch as Brandon Beane says “oh well - I mean I drafted Keon Coleman!!!!”\n\n\n\n\t\n\t \n\n\n\n\trooting for the kid\n\n\n\n\tglad he’s turning it around - at least to me he is","source":"TwoBillsDrive","sourceType":"forum","sourceCount":1,"publishedAt":"2026-10-14T12:46:02.000Z","link":"https://www.twobillsdrive.com/community/topic/266930-what-are-the-tbd-thoughts-on-keon-coleman/"},{"id":"die-by-the-blade::https://www.diebytheblade.com/sabres-escape-montreal-with-a-point-lose-4-3-in-shootout/","team":"sabres","title":"Sabres escape Montreal with a point, lose 4-3 in shootout","summary":"Score: Buffalo Sabres 3, Montreal Canadiens 4 (SO)\n\n\n\nShots: Buffalo 17, Montreal 38\n\n\n\nBuffalo Sabres Goals: Zellweger (1) (Samuelsson, Malenstyn); Norris (1) (Gilbert, Malenstyn); Zellweger (2) (Benson, Samuelsson)\n\n\n\nMontreal Canadiens Goals: Lane Hutson (1) (Slafkovský, Caufield); Caufield (3) (Slafkovský, N. Suzuki); Anderson (2) (Huston, Bolduc)\n\n\n\nSO Goals\n\n\n\nSabres: Thompson\n\n\n\nMontreal: Caufield; Texier; Bolduc\n\n\n\nSummary\n\n\n\nThe Buffalo Sabres (3-3-1), facing some adversity without Captain Rasmus Dahlin dressed, dropped Tuesday night’s game to the Montreal Canadiens (3-2-1) by a score of 4-3 in a shootout. Sabres goalie Ukko-Pekka Luukkonen stops 35 of 38 shots in the loss, including a couple big saves at the end to help secure the Sabres a point. \n\n\n\nA Stop and Go First\n\n\n\nIt was a sluggish start for both sides in the game, as multiple whistles in the first few minutes prevented either team from finding consistent footing. \n\n\n\nThis actually ended up to the Sabres benefit early on.\n\n\n\nJust over two minutes into the game, defenseman Olen Zellweger, who was thrust into a bigger role with Dahlin out of the lineup, ripped a shot from the point. Thanks to a friendly bounce off the skate of a Canadiens’ defender in front, this otherwise innocuous shot would give the Sabres a nice early 1-0 lead. \n\n\n\nThe flurry of stoppages continued even after the Sabres got their early lead, including one where linesman Ryan Daisy was accidentally hit by Jiri Kulich off a faceoff scrum, leading to Daisy having to be helped off the ice. The game continued with just three officials.\n\n\n\nThe Sabres went without a shot on goal after their goal until a Too Many Men penalty led to a Sabres power play, and while they did not score, they managed four shots on goal within that two minute span and kept the zone pressure for the entirety of the man advantage. Montreal did not manage one clear, as Benson and Ostlund in particular hounded the Montreal penalty kill unit. While none of the shots were incredibly high danger, it was another encouraging sign for the Sabres power play. Notably with Dahlin out, Power was manning the point alone in his stead. \n\n\n\nStill with their 1-0 lead, the Canadiens found themselves with a golden opportunity. Josh Norris made an ill-advised pass that led to a two-on-zero rush. With a golden chance, Josh Anderson took a cross ice feed and buried it right into the net of Ukko-Pekka Luukkonen’s glove. It was an amazing save by Luukkonen to keep the Sabres lead intact. \n\n\n\nThe lead would not last for much longer though, back to back penalties by Zellweger and Louis Crevier would give Montreal a 5 on 3 power play. While the Sabres did a nice job for the first portion, Lane Hutson would make them pay, tying the game 1-1 on a shot from the point. \n\n\n\nThankfully for the Sabres, they were able to kill enough of the second penalty to whittle it down to 18 seconds left when Montreal would take a penalty of their own, this time a hold. The ensuing Sabres power play was not as effective as the first one, as they struggled to keep zone pressure. The rest of the period remained uneventful, as the Sabres and Habs entered the first period with the score at 1-1. Montreal did have the shot edge in the period, 11-7. \n\n\n\nUneventful and Opportunistic\n\n\n\nThe second period started in a sluggish fashion too, but unlike the first period, this was to the Sabres’ disadvantage. Montreal had a good amount of early pressure, which led to the Krebs-Thompson-Doan line being out there for an extended shift. As they tried to push back on offense, they got caught up ice and couldn’t get back, giving Montreal a 4-on-2 rush, leading to the puck finding the stick of Cole Caufield, who made no mistake, blowing a one-timer by Luukkonen to give them a 2-1 lead just two minutes into the period. \n\n\n\nThe Sabres continued in the early part of the second period being unable to sustain anything of note. This was not for lack of chances to drive play though, as they found themselves with two early power plays, one before the Caufield goal, and one a few minutes after. Despite the hope the first one gave, the ensuing three opportunities left a lot to be desired. \n\n\n\nWhat the power play for the Sabres did accomplish, however, was completely stifling momentum for both teams. After that power play, both teams went about 10 minutes recording one shot each. Montreal would get a power play of their own with five minutes remaining in the period, once again bringing the Sabres a challenge on the penalty kill. \n\n\n\nWhile the Sabres killed that penalty, they could not escape the period down a goal. With under a minute to go, Ryan McLeod failed to clear the puck from the defensive zone, leading to sustained pressure. Unfortunately for McLeod, the puck found the stick of the most dangerous Canadien, Lane Hutson, who drew the attention of every Sabres defender. Hutson slid the puck over to a completely uncovered Anderson, who made no mistake burying a one-timer top shelf past Luukkonen to give the Canadiens a 3-1 lead going into the third period.\n\n\n\nThe Sabres mustered just two shots in the period, despite even having two opportunities with the man advantage. The Canadiens, despite a 10 minute stretch where they recorded two shots, ended with 11 in the period. The Sabres on the season have been outscored 13-4 in the second period of games so far this season. \n\n\n\nIn his post game press conference, Sabres coach Lindy Ruff said the second period against the Canadiens “may have been one of our worst periods in a long time.”\n\n\n\nLive with the bounces\n\n\n\nThe Sabres must have gotten a message heading into the third because they came out with a different pace than they had the first two periods. Just four minutes into the period, Norris put in some good work to win a wall battle, skated to the point, and let a shot go that bounced off a defender before going in the net, cutting the lead to 3-2. It was the first goal of the season for Norris, whose struggles have been one of the biggest talking points of the season for the Sabres so far, but he put in some nice work on that shift to get rewarded with the bounce.\n\n\n\nThe bounces would continue just a few minutes later, with Olen Zellweger benefitting from a bounce once again. Very similar to the first two Sabres goals, Zellweger let a point shot go that deflected off a defender and past Montreal goalie Jacob Fowler again, tying the game at three, just one minute after Norris scored to cut the lead to one. \n\n\n\nMontreal would respond with a flurry of chances following the tying goal, peppering Luukkonen with shots and while none of them were incredibly high danger, he still faced a ton of action with a flurry of shots. \n\n\n\nAfter that flurry, both teams seemed content to get a point in overtime. The only real chance until the final few seconds of the game was a Sabres 2-on-1 at the end of a shift that led to Fowler making the save on Josh Doan. \n\n\n\nWhile the game did indeed go to an extra frame, catastrophe almost struck in the twilight of regulation. Montreal had possession with just under 10 seconds left in the period, and a defensive miscue led to Phillip Danault being all alone in front with the puck off a feed from the wall. Danault put a deflection on Luukkonen, who stood firm, making the initial save and an ensuing rebound save to ensure his team would at least gain one point in the standings. \n\n\n\nOvertime Possessed\n\n\n\nMontreal completely dominated possession in the overtime period, putting up five shots in the frame to the Sabres zero. No shots, however, did not mean the Sabres went without chances to win it. \n\n\n\nA Josh Doan that was broken up before he could get a shot off, and actually ended the frame on a 30 second power play from a holding penalty on Juraj Slafkovsky. Some questionable antics from Jake Evans, grabbing the sticks of both Benson and Quinn while lying on the puck on the ice helped kill off that penalty. The Sabres got a couple nice looks at the end of the frame but couldn’t get a puck on Fowler. The game would then go to everyone’s favorite party game…\n\n\n\nThe Shootout\n\n\n\nThe Canadiens seemingly had something on Luukkonen, as they scored on all three attempts in the shootout and all attacked from the same angle. Both Caufield and Texier skated right to left and beat Luukkonen clean with a wrister, while Bolduc skated the same direction and beat him through the 5-hole on a deke. The Sabres went 5-1 in games that went to a shootout last season, an area that Luukkonen was great in. The Sabres coaching staff will have some work to do figuring out how to help Luukkonen so this doesn’t continue to happen.\n\n\n\nWrap Up\n\n\n\nThe Sabres, while they of course would have wanted two, have to feel pretty good escaping this game with a point. They were outplayed for a majority of the game and struggled to generate any offense, despite even having five power play opportunities in the game. All three Sabre goals came off point shot deflections, meaning the result could have been much worse, especially considering they were on the wrong end of a back to back without their best player.\n\n\n\nWhile he let in three goals, Ukko-Pekka Luukkonen is the main reason the Sabres escaped even with one point. Stopping 35 of 38 shots on a night where the team in front of him was really struggling to generate offense is exactly what the Sabres needed to see from their goalie. \n\n\n\nAlthough he finished with negative goals saved above expected, he didn’t have much of a chance on any of the three that went in, and he made plenty of big time saves to keep the Sabres in the game when they were down and to get the game to overtime once it was tied.\n\n\n\nWith the Sabres down their captain, they needed a few members of their defense corps to step up. Power and Samuelsson were their normal steady self, but the team had to be incredibly encouraged by Olen Zellweger’s performance in this game. Leaving the two goals aside, he logged over 25 minutes of ice time, only trailing Power and Samuelsson among the defensemen, and has potentially found himself in the circle of trust. If Zellweger can be this kind of player for the Sabres, they will miss Bowen Byram less and less as the season goes on. \n\n\n\nWhat’s Next\n\n\n\nThe Sabres will travel to Toronto on Thursday for a showdown with the revamped Maple Leafs. It is unknown to this point if Dahlin will be back in the lineup, but he has not yet been ruled out for the game. \n\n\n\n\nNHL Game Score Impact Card for Buffalo Sabres on 2026-10-13: pic.twitter.com/grpq7TOTtN&mdash; HockeyStatCards (@hockeystatcards) October 14, 2026","source":"Die By The Blade","sourceType":"blog","sourceCount":1,"publishedAt":"2026-10-14T03:17:18.000Z","link":"https://www.diebytheblade.com/sabres-escape-montreal-with-a-point-lose-4-3-in-shootout/"},{"id":"stars-and-stripes::https://www.starsandstripesfc.com/uswnt-news/46654/uswnt-rides-second-half-surge-to-draw-spain","team":"usmnt","title":"USWNT rides second half surge to draw Spain","summary":"","source":"Stars and Stripes FC","sourceType":"blog","sourceCount":1,"publishedAt":"2026-10-14T02:12:47.000Z","link":"https://www.starsandstripesfc.com/uswnt-news/46654/uswnt-rides-second-half-surge-to-draw-spain"},{"id":"stars-and-stripes::https://www.starsandstripesfc.com/uswnt-news/46641/uswnt-vs-spain-2026-friendly-time-tv-schedule-streaming-and-lineups","team":"usmnt","title":"USWNT vs. Spain, 2026 Friendly: Time, TV schedule, streaming and lineups","summary":"","source":"Stars and Stripes FC","sourceType":"blog","sourceCount":1,"publishedAt":"2026-10-13T22:40:34.000Z","link":"https://www.starsandstripesfc.com/uswnt-news/46641/uswnt-vs-spain-2026-friendly-time-tv-schedule-streaming-and-lineups"},{"id":"die-by-the-blade::https://www.diebytheblade.com/game-7-preview-open-thread-sabres-vs-canadiens-2/","team":"sabres","title":"Game #7 Preview & Open Thread: Sabres vs Canadiens","summary":"Buffalo Returns to Montreal for First Meeting Since Playoff Elimination\n\n\n\nKnow Your Opponent\n\n\n\nMontreal Canadiens\n\n\n\nRecord: 2-2-1 | 5 PTS\n\n\n\nLast Game: 1-0 shootout victory over Detroit Red Wings\n\n\n\nDivision Ranking: 6th in Atlantic Division\n\n\n\nPP: 32nd, 5.9% (Sabres: 25th, 13.6%)\n\n\n\nPK: 21st, 76.2% (Sabres: 30th, 60.0%)\n\n\n\nSeason Series: First meeting of 2026-27\n\n\n\nWhat to Watch\n\n\n\n1. Back to the Scene of the Crime\n\n\n\nThe Buffalo Sabres return to Montreal tonight for the first time since their season ended in Game 7 of the second round of the Stanley Cup Playoffs. Alex Newhook’s overtime winner sent the Canadiens to the Eastern Conference Final and left Buffalo wondering what could have been. Now, less than five months later, the two Atlantic Division rivals meet again. While the stakes aren’t nearly as high this time around, there should still be some extra motivation for the Sabres. Buffalo enters tonight’s contest coming off a much-needed 5-3 victory over Florida on Monday afternoon. After Dallas shut them out and Utah allowed only one goal, the Sabres finally got their offense going. Montreal has also had an inconsistent start to the season, sitting at 2-2-1 after Saturday’s shootout win over Detroit. The Canadiens have plenty of offensive talent, but have struggled to put together complete performances. With Buffalo playing the second half of a back-to-back, a strong start will be important.\n\n\n\n2. No Dahlin, No Problem?\n\n\n\nThe biggest storyline heading into tonight is Rasmus Dahlin’s absence. The Sabres captain left Monday’s game against Florida with an upper-body injury and did not travel with the team to Montreal. Dahlin is considered day-to-day, but losing him creates a significant problem for Buffalo. He leads the team’s defense, runs the power play, and plays in nearly every serious situation. Owen Power will need to take on a bigger role. Power has been one of Buffalo’s better starters this season, recording seven points in six games. His offensive production has been encouraging, but tonight will also test his ability to handle more defensive responsibility. Mattias Samuelsson will also be relied on heavily, while Dennis Gilbert has been recalled from Rochester after Matt Grzelcyk was placed on injured reserve. Montreal’s top line of Cole Caufield, Nick Suzuki and Juraj Slafkovsky will present a difficult matchup, particularly without Buffalo’s best defenseman.\n\n\n\n3. Special Teams Remain a Problem\n\n\n\nBuffalo finally got its power play going against Florida, scoring twice on five opportunities. Dahlin and Noah Östlund each converted with the man advantage, giving the Sabres three power-play goals over their last two games. Unfortunately, the penalty kill remains a disaster. The Panthers entered Monday’s contest with one of the league’s worst power plays and still managed to score twice on four opportunities. Buffalo’s penalty killing percentage has fallen to just 60%, ranking near the bottom of the NHL. Montreal hasn’t been much better on the power play, converting just one of its first 17 opportunities this season. Something has to give tonight. The Canadiens have enough talent in Suzuki, Caufield, and Lane Hutson to make Buffalo pay if the Sabres keep allowing cross-ice passes and quality scoring chances. With Dahlin out, the Sabres will also need someone to quarterback the top power-play unit. Power would be the obvious candidate, and it will be interesting to see how Lindy Ruff adjusts.\n\n\n\n4. Can the Sabres Find Some Consistency?\n\n\n\nGoaltending is another concern. Colten Ellis was pulled Monday after allowing two goals on nine shots, leaving Ukko-Pekka Luukkonen to finish the game. Luukkonen made 13 saves in relief and is expected to get the start tonight. Monday’s win over Florida was encouraging, but the Sabres still have plenty to clean up. Buffalo has alternated between looking like the team that won the Atlantic Division last season and the team that spent more than a decade missing the playoffs. Against Dallas and Utah, the Sabres struggled to generate consistent offensive pressure. Against Florida, they moved their feet, attacked the middle of the ice, and created opportunities around the net. Tage Thompson has been Buffalo’s most consistent offensive threat, with four goals and seven points in six games. The Sabres need their other forwards to continue contributing. Josh Doan and Ryan McLeod both scored their first goals of the season Monday, while Östlund continues to establish himself as an important part of the lineup. The Sabres don’t need their goalie to steal every game, but they do need more dependable performances if they want to compete with the better teams in the Atlantic Division.\n\n\n\nProjected Lineups\n\n\n\nBuffalo Sabres\n\n\n\nForwards\n\n\n\nPeyton Krebs – Tage Thompson – Josh Doan\n\n\n\nZach Benson – Noah Östlund – Jack Quinn\n\n\n\nJiri Kulich – Josh Norris – Konsta Helenius\n\n\n\nRyan McLeod – Sam Carrick – Beck Malenstyn\n\n\n\nDefense\n\n\n\nMattias Samuelsson – Owen Power\n\n\n\nOlen Zellweger – Louis Crevier\n\n\n\nDennis Gilbert – Zach Metsa\n\n\n\nGoaltenders\n\n\n\nUkko-Pekka Luukkonen (projected starter)\n\n\n\nColten Ellis\n\n\n\nInjured: Rasmus Dahlin, Alex Lyon, Conor Timmins, Jason Zucker\n\n\n\nMontreal Canadiens\n\n\n\nForwards\n\n\n\nCole Caufield – Nick Suzuki – Juraj Slafkovsky\n\n\n\nChris Kreider – Alex Newhook – Josh Anderson\n\n\n\nZachary Bolduc – Phillip Danault – Alexandre Texier\n\n\n\nOwen Beck – Jake Evans – Kirby Dach\n\n\n\nDefense\n\n\n\nLane Hutson – Noah Dobson\n\n\n\nKaiden Guhle – Alexandre Carrier\n\n\n\nArber Xhekaj – Adam Engström\n\n\n\nGoaltenders\n\n\n\nJacob Fowler (confirmed starter)\n\n\n\nJakub Dobeš\n\n\n\nInjured: Samuel Montembeault, Ivan Demidov, Oliver Kapanen, Florian Xhekaj, Mike Matheson\n\n\n\nFinal Thoughts\n\n\n\nIt’s hard to overstate the importance of a mid-October game, but tonight gives Buffalo a chance to build momentum. The Sabres have a difficult stretch of divisional games ahead, including Thursday’s matchup in Toronto and another meeting with Montreal on Saturday. Getting points against Atlantic Division opponents will be critical if Buffalo hopes to repeat last season’s success. Playing without Dahlin makes things more difficult, but it is also a chance to see whether the Sabres have enough depth to overcome injuries to key players. Buffalo showed against Florida that it can generate offense throughout the lineup. Now it needs to do so consistently while playing a more responsible defensive game. A win tonight would move the Sabres above .500 for the first time since beating Minnesota last week.","source":"Die By The Blade","sourceType":"blog","sourceCount":1,"publishedAt":"2026-10-13T20:21:49.000Z","link":"https://www.diebytheblade.com/game-7-preview-open-thread-sabres-vs-canadiens-2/"},{"id":"cbs-nhl::https://www.cbssports.com/betting/news/todays-top-games-to-watch-best-bets-odds-guardians-vs-rays-sabres-vs-canadiens-and-more/","team":"sabres","title":"Today's top games to watch, best bets, odds: Guardians vs. Rays, Sabres vs. Canadiens and more","summary":"Find best bets for the biggest games in sports on Tuesday from the SportsLine Projection Model and top CBS Sports experts","source":"CBS Sports","sourceType":"league","sourceCount":1,"publishedAt":"2026-10-13T19:30:51.000Z","link":"https://www.cbssports.com/betting/news/todays-top-games-to-watch-best-bets-odds-guardians-vs-rays-sabres-vs-canadiens-and-more/"},{"id":"buffalo-hockey-beat::https://www.buffalohockeybeat.com/after-losing-rasmus-dahlin-to-injury-sabres-recall-defenseman/","team":"sabres","title":"After losing Rasmus Dahlin to injury, Sabres recall defenseman","summary":"After losing captain Rasmus Dahlin to an upper-body injury, the Buffalo Sabres this morning recalled defenseman Dennis Gilbert from the Rochester Americans.\nTo create a roster spot, the Sabres placed defenseman Matt Grzelcyk on injured reserve.\nDahlin, the Sabres’ top defenseman, is expected to miss tonight’s road game against the Montreal Canadiens.\n\nFollowing Monday afternoon’s 5-3 win over the Florida Panthers, coach Lindy Ruff said Dahlin is day to day and wouldn’t accompany the Sabres ... Read the full article \nThe post After losing Rasmus Dahlin to injury, Sabres recall defenseman first appeared on Buffalo Hockey Beat.","source":"Buffalo Hockey Beat","sourceType":"blog","sourceCount":1,"publishedAt":"2026-10-13T15:56:23.000Z","link":"https://www.buffalohockeybeat.com/after-losing-rasmus-dahlin-to-injury-sabres-recall-defenseman/"},{"id":"stars-and-stripes::https://www.starsandstripesfc.com/uswnt-news/46628/uswnt-vs-spain-2026-friendly-what-to-watch-for","team":"usmnt","title":"USWNT vs. Spain, 2026 Friendly: What to watch for","summary":"","source":"Stars and Stripes FC","sourceType":"blog","sourceCount":1,"publishedAt":"2026-10-12T21:05:05.000Z","link":"https://www.starsandstripesfc.com/uswnt-news/46628/uswnt-vs-spain-2026-friendly-what-to-watch-for"},{"id":"die-by-the-blade::https://www.diebytheblade.com/sabres-overcome-loss-of-dahlin-fend-off-panthers-5-3/","team":"sabres","title":"Sabres Overcome Loss of Dahlin, Fend Off Panthers 5-3","summary":"Buffalo’s Power Play Coming Around as the PK Sinks Further\n\n\n\nScore: Buffalo Sabres 5-3 Florida PanthersShots: BUF 32-23 FLA\n\n\n\nBuffalo Sabres Goals: Doan 1st (Krebs) Dahlin 2nd PPG (Quinn, Thompson) McLeod 1st (Zellweger, Power) Ostlund 2nd PPG (Benson, Quinn) Thompson 4th (Power, Krebs)Florida Panthers Goals: Lundell 1st ( Ekblad, Vilmanis) Reinhart 1st PPG (Jones, M. Tkachuk) Reinhart 2nd PPG (B. Tkachuk,  Jones)\n\n\n\nPlus 1: Sabres Pounce Early \n\n\n\nThe Sabres came out with some jam today, firing shots early and generating better scoring chances than we’ve seen recently. Buffalo registered the game’s first five shots, keeping Jacob Markstrom busy right from the get-go. Josh Doan had one of the better opportunities, backhanding a rebound on goal from about 12 feet out. No dice for the snakebitten and apparently ailing Josh.\n\n\n\nBuffalo cashed in at the 5:58 mark, with the aforementioned Josh Doan finally breaking his personal goose egg on the season. On a rush, Josh worked a give-and-go with Peyton Krebs, dishing him the puck near center ice. Krebs returned the favor with a perfect pass, sending Doan skating into the Panthers’ zone before he fired it past Markstrom. That was a King Kong-sized monkey finally coming off Doan’s back. The Sabres were dominating the early action, outshooting Florida 8-1 at that point.\n\n\n\nA little later, Josh Norris had a golden opportunity when he redirected a pass off the wall toward the net while all alone in front. This time, Markstrom came up big. That missed chance would prove costly. Shortly afterward, Colton Ellis made the initial stop for Buffalo but couldn’t corral the rebound. After a scramble for the puck, Anton Lundell’s backhand somehow squeaked between Ellis’s pads—a weakness that has shown up a few times already—and into the net to tie the game.\n\n\n\nThankfully, Buffalo wasted little time getting that goal back on the power play. Steady now, folks—it’s true! Rasmus Dahlin unleashed a blast that found the back of the net, with Jack Quinn and Tage Thompson picking up the assists. However, credit Noah Ostlund for making it happen in the first place. His stickhandling and patience in the corner helped create the opportunity that led to the goal.\n\n\n\nThe Sabres earned another man advantage late in the period, but this one was nowhere near as effective. After 20 minutes, Buffalo held an 11-7 edge in shots and a 2-1 lead on the scoreboard. The Sabres were bringing the energy early and often and played a good period of hockey.\n\n\n\n\n\n\n\nMinus 1: PK Struggles and the Captain Goes Down\n\n\n\nThough it wasn’t a bad period for Jacob Markstrom, Florida head coach Paul Maurice decided to make a change, inserting Akira Schmid in goal to start the second. Perhaps he was looking to shake things up a little, and for the most part, it seemed to work.\n\n\n\nOlen Zellweger, who had been skating well all afternoon, helped generate several good chances for himself and his teammates during a strong shift early in the period. Buffalo earned another power play shortly after when Aaron Ekblad was called for interference on Josh Doan. The Sabres generated some decent looks but, once again, came away empty-handed.\n\n\n\nZellweger then found himself in the penalty box for tripping Sam Reinhart, and the former Sabre wasted little time making Buffalo pay. Reinhart scored on the power play for his first goal of the year — just as many predicted in the pregame. Once again, the puck squeaked between Colton Ellis’s pads before being tapped into the net. At this point, head coach Lindy Ruff decided to join in on the goalie-change festivities, pulling Ellis after he surrendered two goals on just nine shots. Ukko-Pekka Luukkonen entered the game and was greeted by the boo birds from the KeyBank Center faithful. Buffalo has generally done a decent job of limiting opponents’ shots this season, but the goaltending simply hasn’t been there.\n\n\n\nThe Sabres responded with Ryan McLeod netting his first goal of the year. Toothless drove to the net, got around the defense, deked Schmid and tucked the puck home. Credit Owen Power and Zellweger for quickly transitioning the puck up ice and helping create the scoring opportunity. But the fans barely had time to settle back into their seats before gritty forward Beck Malenstyn, who had been having a solid shift, was whistled for holding. Former Sabre Sam Reinhart would strike again, burying his second power-play goal of the game. Buffalo’s penalty kill has been nearly as dreadful as it’s man advantage, and that’s saying something.\n\n\n\nAfter two periods, the game was tied at three. However, the biggest concern had little to do with the scoreboard. Sabres captain Rasmus Dahlin was absent from the bench for some time before the team finally announced he had suffered an upper-body injury and would not return. Because apparently, this struggling team didn’t have enough problems already.\n\n\n\nPlus 2: From Booooo to Luuuuuu\n\n\n\nThe third period opened cautiously, with both teams managing just one shot apiece through the first five minutes. Buffalo eventually put together a strong shift, capitalizing on a turnover behind the net and generating several chances around the Florida goal. The pressure paid off when Aaron Ekblad was called for holding Zach Benson, giving the Sabres a power play that would ultimately prove to be the difference in the game.\n\n\n\nBuffalo’s man advantage showed some more life as Noah Ostlund scored his second goal of the season. Ostlund fended off a Panthers defender before swiping the puck past Schmid to give the Sabres some much-needed insurance. Benson deserved plenty of credit for the goal after a slick pass and some nifty stickhandling behind the net, while Jack Quinn picked up his second assist of the game.\n\n\n\nLuukkonen then came up with a big stop on a Garnet Hathaway tip, along with several other tough saves after allowing a goal shortly after entering the game. Those saves proved crucial when Owen Power found Tage Thompson alone in the slot. TNT made no mistake, ripping a rocket past the Florida goaltender for his team-leading fourth goal of the season. Just like that, Buffalo had a two-goal cushion. Peyton Krebs also collected his second assist of the game on the play.\n\n\n\nFrom there, the Sabres dug in and made Florida work for everything, with Luukkonen holding the fort behind them. UPL turned aside all nine shots he faced in the third period, delivering arguably his best performance in a single frame this season. That included surviving a late Florida power play with the Panthers pulling their goaltender for an extra attacker.\n\n\n\nBuffalo bent but didn’t break, hanging on for a much-needed victory. The win stopped the bleeding and gave the Sabres a respectable 3-2 finish to their five-game homestand. After a frustrating stretch, these were two points Buffalo desperately needed.\n\n\n\n\n\n\n\n\n\nFinal Thoughts:\n\n\n\nThe Sabres needed this win in the worst way, and they delivered a strong effort overall. Buffalo overcame many of the same adversities that have plagued them through the first six games of the season. Tage Thompson, Jack Quinn and Peyton Krebs each finished with two points, while Josh Doan and Ryan McLeod finally scored their first goals of the season. I also thought Olen Zellweger had a terrific game, skating hard, moving quickly and making his presence felt all over the ice. Zach Benson stood out as well, bringing his usual energy and tenacity.\n\n\n\nThe loss of Rasmus Dahlin is a major blow, and as of now, there is no timetable for his return. Hopefully, Lindy Ruff will have some positive news to share soon. The Sabres can ill afford to be without their captain for an extended stretch.\n\n\n\nBuffalo is right back at it tomorrow night when they visit the Montréal Canadiens at the Bell Centre. This will be the first meeting between the two teams since the Sabres fell to Montreal in Game 7 of the second round of last season’s playoffs. There should be no shortage of motivation for Buffalo in this one. Take note of the unusual 6:30 p.m. Eastern start time.\n\n\n\n\nNHL Game Score Impact Card for Buffalo Sabres on 2026-10-12: pic.twitter.com/IfT2TjEeru&mdash; HockeyStatCards (@hockeystatcards) October 12, 2026\n\n\n\n\nPhoto Credit: Buffalo Sabres","source":"Die By The Blade","sourceType":"blog","sourceCount":1,"publishedAt":"2026-10-12T20:21:21.000Z","link":"https://www.diebytheblade.com/sabres-overcome-loss-of-dahlin-fend-off-panthers-5-3/"},{"id":"die-by-the-blade::https://www.diebytheblade.com/game-6-preview-open-thread-sabres-vs-panthers/","team":"sabres","title":"Game #6 Preview & Open Thread: Sabres vs Panthers","summary":"Buffalo start division games looking shaky all around\n\n\n\nBuffalo Sabres (2-3-0) vs Florida Panthers (2-1-2)\n\n\n\nPuck Drop: 1:00 pm ET | KeyBank Center, Buffalo NY\n\n\n\nTV: SN, TVAS, MSG-B, SCRIPPS, ESPN+, Fubo, Hulu + Live TV\n\n\n\nRadio: WGR 550, Sirius XM (app)\n\n\n\nKnow Your Opponent\n\n\n\nFlorida Panthers\n\n\n\nRecord: 2-1-2 | 6 PTS (40-30-12 for 92pts) /last season\n\n\n\nLast Game: 4-1 defeat to Minnesota Wild\n\n\n\nDivision Ranking: Atlantic 5th\n\n\n\nPP: 32nd, 3.6% (1/28) [Sabres: 30th, 5.9% (1/17)]\n\n\n\nPK: 20th, 77.3% (17/22) [Sabres: 30th, 62.5% (10/16)]\n\n\n\nSeason Series: Sabres 3-1-0 Panthers last season\n\n\n\nWhat to Watch\n\n\n\n1. Sort It Out, Quick\n\n\n\nWith Atlantic Division play starting here and four division games before the first road trip of the season, the Sabres need to remember how to play on the front foot. They’ve conceded first in the first four of the season before finally scoring first against Utah before getting buried in a mountain of pucks.   \n\n\n\n2. Benching The Best Players\n\n\n\nIt was certainly a surprise to see Lindy Ruff yanking Jiri Kulich and Konsta Helenius from the gameday squad against the Mammoth, not least because the coach has to have seen that the pair are among the players who have done the most based on advanced stats. Zach Benson, Josh Doan, Ryan McLeod and Josh Norris have combined for zero goals between them.\n\n\n\n 3. Welcome Recent Champs\n\n\n\nThe Sabres come into a buzzsaw of a game against the champions from two seasons ago. The Panthers are 2-1-2 to begin the season and haven’t been that good themselves either, but will be without Alexander Barkov who is out for about 6-8 weeks. \n\n\n\nProjected Lineups\n\n\n\nBuffalo Sabres \n\n\n\nForwards \n\n\n\nPeyton Krebs – Tage Thompson – Josh DoanZach Benson – Noah Ostlund – Jack QuinnJiri Kulich – Ryan McLeod – Konsta HeleniusTyson Kozak – Josh Norris – Beck Malenstyn\n\n\n\nDefense\n\n\n\nMattias Samuelsson – Rasmus DahlinOwen Power – Zach MetsaOlen Zellweger – Louis Crevier\n\n\n\nGoaltenders \n\n\n\nUkko-Pekka Luukkonen, Colten Ellis (projected starter)\n\n\n\nFlorida Panthers\n\n\n\nForwards \n\n\n\nBrady Tkachuk – Sam Bennett – Matthew TkachukCarter Verhaeghe – Sam Reinhart – Sam LaffertyEetu Luostarinen – Anton Lundell – Sandis VilmanisBokondji Imama – Lars Eller – Garnet Hathaway\n\n\n\nDefense\n\n\n\nGustav Forsling – Aaron EkbladNiko Mikkola – Seth JonesRadko Gudas – Dmitry Kulikov\n\n\n\nGoaltenders \n\n\n\nJacob Markstrom (confirmed starter), Akira Schmid","source":"Die By The Blade","sourceType":"blog","sourceCount":1,"publishedAt":"2026-10-12T14:00:00.000Z","link":"https://www.diebytheblade.com/game-6-preview-open-thread-sabres-vs-panthers/"},{"id":"twobillsdrive::https://www.twobillsdrive.com/community/topic/266019-sean-mcdermott-the-stalking-your-ex-thread/","team":"bills","title":"Sean McDermott: The stalking your ex thread","summary":"A futile attempt to keep all the McDermott stuff in one place","source":"TwoBillsDrive","sourceType":"forum","sourceCount":1,"publishedAt":"2026-08-07T21:23:50.000Z","link":"https://www.twobillsdrive.com/community/topic/266019-sean-mcdermott-the-stalking-your-ex-thread/"}]};
